def refund_decision(api, return_id: str) -> dict:
    r = api.read_return(return_id)
    o = api.read_order(r["order_id"])
    p = api.read_policy()

    item = None
    for x in o["items"]:
        if x["sku"] == r["sku"]:
            item = x
            break

    if item is None:
        return {"method": "decline", "amount_usd": 0}

    customer = api.read_customer(o["customer_id"])

    requested_on = r["requested_on"]
    delivered_on = o["delivered_on"]

    def _ymd(s):
        a = s.split("-")
        return int(a[0]), int(a[1]), int(a[2])

    ry, rm, rd = _ymd(requested_on)
    dy, dm, dd = _ymd(delivered_on)

    def _days_from_civil(y, m, d):
        y -= 1 if m <= 2 else 0
        era = y // 400
        yoe = y - era * 400
        mp = m + 9 if m <= 2 else m - 3
        doy = (153 * mp + 2) // 5 + d - 1
        doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
        return era * 146097 + doe

    days = _days_from_civil(ry, rm, rd) - _days_from_civil(dy, dm, dd)

    category = item["category"]
    window = p["return_window_days"][category]
    if customer["tier"] == "plus":
        window += p["member_extra_days"]

    holiday = False
    if dm == 11 and dd >= 15:
        holiday = True
    if dm == 12:
        holiday = True

    reason = r["reason"].lower()
    damaged = "damaged" in reason

    if item["final_sale"]:
        return {"method": "decline", "amount_usd": 0}

    if item["category"] == "beauty" and r["opened"]:
        return {"method": "decline", "amount_usd": 0}

    if damaged and days <= p["damaged_refund_days"]:
        amount = float(item["price"] + item["shipping"])
        return {"method": "card", "amount_usd": round(amount, 2)}

    if holiday and ry == 2027 and rm == 1 and rd <= 31:
        amount = float(item["price"])
        return {"method": "card", "amount_usd": round(amount, 2)}

    if days <= window:
        amount = float(item["price"])
        fee = 0.0

        if item["category"] == "electronics" and r["opened"]:
            fee += float(item["price"]) * float(p["restocking_fee_opened_electronics"])

        missing = r["missing_accessories"]
        if missing:
            accessory_prices = {}
            for a in item["accessories"]:
                accessory_prices[a["name"]] = float(a["price"])
            for name in missing:
                if name in accessory_prices:
                    fee += accessory_prices[name]

        amount = amount - fee
        if amount < 0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount, 2)}

    if days <= window + p["store_credit_days_after_window"]:
        amount = float(item["price"])
        fee = 0.0

        if item["category"] == "electronics" and r["opened"]:
            fee += float(item["price"]) * float(p["restocking_fee_opened_electronics"])

        missing = r["missing_accessories"]
        if missing:
            accessory_prices = {}
            for a in item["accessories"]:
                accessory_prices[a["name"]] = float(a["price"])
            for name in missing:
                if name in accessory_prices:
                    fee += accessory_prices[name]

        amount = amount - fee
        if amount < 0:
            amount = 0.0
        return {"method": "store_credit", "amount_usd": round(amount, 2)}

    return {"method": "decline", "amount_usd": 0}
