    reason = ret["reason"]
    opened = ret["opened"]
    missing = ret["missing_accessories"]
    requested_on = ret["requested_on"]
    delivered_on = order["delivered_on"]

    def split_date(s):
        parts = s.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def day_of_year(s):
        y, m, d = split_date(s)
        leap = (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))
        month_days = [31, 28 + (1 if leap else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = d
        for i in range(m - 1):
            total += month_days[i]
        return total

    def days_in_year(y):
        return 366 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 365

    def days_between(a, b):
        ya, ma, da = split_date(a)
        yb, mb, db = split_date(b)
        if ya == yb:
            return day_of_year(b) - day_of_year(a)
        total = days_in_year(ya) - day_of_year(a)
        y = ya + 1
        while y < yb:
            total += days_in_year(y)
            y += 1
        total += day_of_year(b)
        return total

    def month_day(s):
        y, m, d = split_date(s)
        return m, d

    def in_holiday_delivery_window(s):
        m, d = month_day(s)
        return (m == 11 and d >= 15) or m == 12

    def is_by_jan31(s):
        y, m, d = split_date(s)
        return (m == 1 and d <= 31)

    category = item["category"]
    base_window = policy["return_window_days"][category]
    member_extra = policy["member_extra_days"] if customer["tier"] == "plus" else 0
    window_days = base_window + member_extra

    days_since_delivery = days_between(delivered_on, requested_on)

    price = float(item["price"])
    shipping = float(item["shipping"])

    missing_value = 0.0
    accessories = item["accessories"]
    for acc in accessories:
        if acc["name"] in missing:
            missing_value += float(acc["value"])

    if item["final_sale"]:
        return {"method": "decline", "amount_usd": 0.0}

    if reason == "damaged" and days_since_delivery <= policy["damaged_refund_days"]:
        amount = price + shipping
        return {"method": "card", "amount_usd": round(amount + 1e-9, 2)}

    if opened and category == "beauty":
        return {"method": "decline", "amount_usd": 0.0}

    if days_since_delivery <= window_days:
        amount = price - missing_value
        if opened and category == "electronics":
            if not (in_holiday_delivery_window(delivered_on) and is_by_jan31(requested_on)):
                amount = amount - (price * policy["restocking_fee_opened_electronics"])
        if amount < 0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount + 1e-9, 2)}

    if days_since_delivery <= window_days + policy["store_credit_days_after_window"]:
        amount = price - missing_value
        if opened and category == "electronics":
            if not (in_holiday_delivery_window(delivered_on) and is_by_jan31(requested_on)):
                amount = amount - (price * policy["restocking_fee_opened_electronics"])
        if amount < 0:
            amount = 0.0
        return {"method": "store_credit", "amount_usd": round(amount + 1e-9, 2)}

    return {"method": "decline", "amount_usd": 0.0}
