        return (int(s[0:4]), int(s[5:7]), int(s[8:10]))

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def dim(y, m):
        if m == 1 or m == 3 or m == 5 or m == 7 or m == 8 or m == 10 or m == 12:
            return 31
        if m == 4 or m == 6 or m == 9 or m == 11:
            return 30
        return 29 if is_leap(y) else 28

    def date_to_ordinal(s):
        y, m, d = to_ymd(s)
        days = 0
        for yy in range(1, y):
            days += 366 if is_leap(yy) else 365
        for mm in range(1, m):
            days += dim(y, mm)
        days += d
        return days

    req_day = date_to_ordinal(requested_on)
    del_day = date_to_ordinal(delivered_on)
    days_since_delivery = req_day - del_day

    # Holiday return override
    y, m, d = to_ymd(delivered_on)
    holiday_delivery = False
    if m == 11 and d >= 15:
        holiday_delivery = True
    if m == 12:
        holiday_delivery = True
    holiday_deadline = False
    ry, rm, rd = to_ymd(requested_on)
    if ry == y and rm == 1 and rd <= 31:
        holiday_deadline = True
    if holiday_delivery and holiday_deadline:
        amount = price - accessory_value
        if amount < 0.0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount, 2)}

    # Damaged item override
    if reason == "damaged" and days_since_delivery <= int(policy["damaged_refund_days"]):
        amount = price + shipping
        return {"method": "card", "amount_usd": round(amount, 2)}

    # Standard return rules
    if final_sale:
        return {"method": "decline", "amount_usd": 0.0}

    window_days = policy["return_window_days"][category]
    tier = ""
    if customer is not None and "tier" in customer:
        tier = customer["tier"]
    if tier == "plus":
        window_days += int(policy["member_extra_days"])

    if days_since_delivery <= window_days:
        if category == "electronics" and opened:
            amount = price * (1.0 - float(policy["restocking_fee_opened_electronics"]))
        elif category == "beauty" and opened:
            return {"method": "decline", "amount_usd": 0.0}
        else:
            amount = price
        amount -= accessory_value
        if amount < 0.0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount, 2)}

    if days_since_delivery <= window_days + int(policy["store_credit_days_after_window"]):
        if category == "beauty" and opened:
            return {"method": "decline", "amount_usd": 0.0}
        amount = price
        if category == "electronics" and opened:
            amount = price * (1.0 - float(policy["restocking_fee_opened_electronics"]))
        amount -= accessory_value
        if amount < 0.0:
            amount = 0.0
        return {"method": "store_credit", "amount_usd": round(amount, 2)}

    return {"method": "decline", "amount_usd": 0.0}
