    def to_ymd(s):
        parts = s.split("-")
        return [int(parts[0]), int(parts[1]), int(parts[2])]

    def is_leap(y):
        return y % 400 == 0 or (y % 4 == 0 and y % 100 != 0)

    def day_index(s):
        y, m, d = to_ymd(s)
        mdays = [31, 28 + (1 if is_leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = d
        for i in range(m - 1):
            total += mdays[i]
        return y * 366 + total

    def days_between(a, b):
        return day_index(b) - day_index(a)

    def day_of_year(s):
        y, m, d = to_ymd(s)
        mdays = [31, 28 + (1 if is_leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = d
        for i in range(m - 1):
            total += mdays[i]
        return total

    def month_day_to_index(year, month, day):
        mdays = [31, 28 + (1 if is_leap(year) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = day
        for i in range(month - 1):
            total += mdays[i]
        return total

    category = item["category"]
    window = p["return_window_days"][category]
    if is_member:
        window += p["member_extra_days"]

    days_since_delivery = days_between(delivered_on, requested_on)
    inside_window = days_since_delivery <= window
    after_window_credit = days_since_delivery <= window + p["store_credit_days_after_window"]

    y, m, d = to_ymd(delivered_on)
