            nights.append(float(r["amount"]) * float(rates[r["currency"]]))

    hotel_total = 0.0
    for h in nights:
        hotel_total += h
    if hotel_total > 0.0:
        max_hotel = float(allowances["hotel_per_night"]) * len(nights)
        if hotel_total > max_hotel:
            hotel_total = max_hotel

    other_total = 0.0
    for r in receipts:
        cat = r["category"]
