    def to_ymd(s):
        parts = s.split("-")
        return int(parts[0]), int(parts[1]), int(parts[2])

    def leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def dim(y, m):
        ds = [31, 28 + (1 if leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return ds[m - 1]

