    def _date_parts(s):
        a = s.split("-")
        return int(a[0]), int(a[1]), int(a[2])

    def _days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        if m in (4, 6, 9, 11):
            return 30
        leap = False
        if y % 400 == 0:
            leap = True
        elif y % 100 == 0:
            leap = False
        elif y % 4 == 0:
            leap = True
        return 29 if leap else 28

    def _days_from_epoch(s):
        y, m, d = _date_parts(s)
        days = 0
        yy = 1
        while yy < y:
            leap = False
            if yy % 400 == 0:
                leap = True
            elif yy % 100 == 0:
                leap = False
            elif yy % 4 == 0:
                leap = True
            days += 366 if leap else 365
            yy += 1
        mm = 1
        while mm < m:
            days += _days_in_month(y, mm)
            mm += 1
        return days + d

    req_days = _days_from_epoch(requested)
    del_days = _days_from_epoch(delivery)
    delta_days = req_days - del_days

    category = item["category"]
    window = p["return_window_days"][category] + extra_days

    y, m, d = _date_parts(delivery)
    holiday = False
    if (m == 11 and d >= 15) or (m == 12) or (m == 1 and d <= 31):
        holiday = True

    damaged = str(r["reason"]) == "damaged"
    opened = bool(r["opened"])
    final_sale = bool(item["final_sale"])

