        amount = float(item["price"]) + float(item["shipping"])
        method = "card"
    elif final_sale:
        method = "decline"
        amount = 0.0
    elif category == "beauty" and opened:
        method = "decline"
        amount = 0.0
    else:
        if delta_days <= window:
            method = "card"
        elif delta_days <= window + p["store_credit_days_after_window"]:
            method = "store_credit"
        else:
            method = "decline"

        if method != "decline":
            amount = float(item["price"])
            if opened and category == "electronics" and not holiday:
                amount = amount * (1.0 - float(p["restocking_fee_opened_electronics"]))
            miss = r["missing_accessories"]
            accessory_values = 0.0
            for a in item["accessories"]:
                for m2 in miss:
                    if a["name"] == m2:
                        accessory_values += float(a["value"])
                        break
            amount = amount - accessory_values

    amount = round(amount + 1e-12, 2)

    if method == "decline":
        return {"method": "decline", "amount_usd": 0.0}

    api.issue_refund({"return_id": return_id, "amount_usd": amount, "method": method})
    return {"method": method, "amount_usd": amount}
