    policy = api.read_policy()

    sku = r["sku"]
    item = None
    for x in order["items"]:
        if x["sku"] == sku:
            item = x
            break

    if item is None:
        return api.decline_return(return_id)

    ordered_on = order["ordered_on"]
    delivered_on = order["delivered_on"]
    requested_on = r["requested_on"]

    def date_parts(s):
        p = s.split("-")
        return [int(p[0]), int(p[1]), int(p[2])]

    def to_ordinal(s):
        y, m, d = date_parts(s)
        leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
        mdays = [31, 28 + (1 if leap else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        total = 0
        yy = 1
        while yy < y:
            leap2 = (yy % 4 == 0 and yy % 100 != 0) or (yy % 400 == 0)
            total += 366 if leap2 else 365
            yy += 1
        mm = 1
        while mm < m:
            total += mdays[mm - 1]
            mm += 1
        total += d
        return total

    def days_between(a, b):
        return to_ordinal(b) - to_ordinal(a)

    def is_holiday_delivery(s):
        p = date_parts(s)
        return p[1] == 11 and p[2] >= 15 or p[1] == 12 or p[1] == 1 and p[2] <= 31

    base_window = policy["return_window_days"][item["category"]]
    extra = 0
    if customer is not None and customer["tier"] == "plus":
        extra = policy["member_extra_days"]
    window_days = base_window + extra

    days_from_delivery = days_between(delivered_on, requested_on)
    inside_window = days_from_delivery <= window_days
    within_credit = days_from_delivery <= window_days + policy["store_credit_days_after_window"]

    damaged = r["reason"] == "damaged"

    if damaged:
        if days_from_delivery <= policy["damaged_refund_days"]:
            return {"method": "card", "amount_usd": round(item["price"] + item["shipping"], 2)}
        return {"method": "decline", "amount_usd": 0}

    if item["final_sale"]:
        return {"method": "decline", "amount_usd": 0}

    if item["category"] == "beauty" and r["opened"]:
        return {"method": "decline", "amount_usd": 0}

    if not inside_window and not within_credit:
        return {"method": "decline", "amount_usd": 0}

    amount = item["price"]

    if r["opened"] and item["category"] == "electronics" and not is_holiday_delivery(delivered_on):
        amount = amount * (1 - policy["restocking_fee_opened_electronics"])

    missing = r["missing_accessories"]
    if len(missing) > 0:
        for acc in item["accessories"]:
            for name in missing:
                if acc["name"] == name:
                    amount -= acc["value"]

    if amount < 0:
        amount = 0

    amount = round(amount, 2)

    if inside_window or (is_holiday_delivery(delivered_on) and requested_on <= "2027-01-31"):
        return {"method": "card", "amount_usd": amount}

    return {"method": "store_credit", "amount_usd": amount}
