def reimbursable_total(api, trip_id: str) -> dict:
    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    city = trip.get("city", "")
    start = trip.get("start", "")
    month = start[:7]

    allowances = policy.get("allowances_usd", {})
    city_policy = allowances.get(city, {})
    meal_allowance = float(city_policy.get("meals_per_day", 0.0))
    hotel_allowance = float(city_policy.get("hotel_per_night", 0.0))

    rates_by_month = policy.get("company_rates_usd_per_unit", {})
    month_rates = rates_by_month.get(month, {})
    trip_currency = ""
    receipts = trip.get("receipts", [])
    if len(receipts) > 0:
        trip_currency = receipts[0].get("currency", "")

    def to_usd(amount, currency):
        if currency == "USD":
            return float(amount)
        rate = month_rates.get(currency)
        if rate is None:
            return 0.0
        return float(amount) * float(rate)

    def has_alcohol(note):
        note_text = str(note).lower()
        return "alcohol" in note_text

    def taxi_ok(receipt_usd, note):
        if receipt_usd <= 40.0:
            return True
        return len(str(note).strip()) > 0

    day_meals = {}
    total = 0.0

    for receipt in receipts:
        category = receipt.get("category", "")
        note = receipt.get("note", "")
        amount = receipt.get("amount", 0.0)
        currency = receipt.get("currency", trip_currency)

        if has_alcohol(note):
            continue

        usd = to_usd(amount, currency)

        if category == "meal":
            date = receipt.get("date", "")
            spent = day_meals.get(date, 0.0)
            remaining = meal_allowance - spent
            if remaining > 0:
                reimb = min(usd, remaining)
                day_meals[date] = spent + reimb
                total += reimb

        elif category == "hotel":
            total += min(usd, hotel_allowance)

        elif category == "taxi":
            if taxi_ok(usd, note):
                total += usd

        else:
            total += 0.0

    return {"total_usd": round(total, 2)}
