            except Exception:
                customer = None

    items = order.get("items", []) if isinstance(order, dict) else []
    item = None
    target_sku = r.get("sku") if isinstance(r, dict) else None
    for x in items:
        if isinstance(x, dict) and x.get("sku") == target_sku:
            item = x
            break

    if item is None and isinstance(items, list) and len(items) == 1:
        item = items[0]

    if item is None:
        try:
            api.decline_return(return_id)
        except Exception:
            pass
        return {"method": "decline", "amount_usd": 0.0}

    category = item.get("category")
    price = float(item.get("price", 0.0))
    shipping = float(item.get("shipping", 0.0))
    final_sale = bool(item.get("final_sale", False))
    opened = bool(r.get("opened", False))
    missing = r.get("missing_accessories", [])
    requested_on = r.get("requested_on")
    delivered_on = order.get("delivered_on")

