        extra_days = int(policy.get("member_extra_days", 0))
        tier = ""
        if isinstance(customer, dict):
            tier = str(customer.get("tier", ""))
        if tier == "plus":
            window_days += extra_days

    holiday = False
    if isinstance(delivered_on, str) and len(delivered_on) >= 10:
        m = int(delivered_on[5:7])
        d = int(delivered_on[8:10])
        if m == 11 and d >= 15:
            holiday = True
        if m == 12:
            holiday = True

    def _days(s):
        if not isinstance(s, str) or len(s) < 10:
            return 0
        y = int(s[0:4])
        m = int(s[5:7])
        d = int(s[8:10])
        return y * 372 + m * 31 + d

    days_since_delivery = _days(requested_on) - _days(delivered_on)

    if final_sale:
        try:
            api.decline_return(return_id)
        except Exception:
            pass
        return {"method": "decline", "amount_usd": 0.0}

