def reimbursable_total(api, trip_id: str) -> dict:
    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    city = trip["city"]
    start = trip["start"]
    receipts = trip.get("receipts", [])

    allowances = policy["allowances_usd"][city]
    rates = policy["company_rates_usd_per_unit"]

    month = start[:7]
    rate_table = rates[month]

    year = int(start[:4])
    month_num = int(start[5:7])
    day = int(start[8:10])

    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def dim(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        if m in (4, 6, 9, 11):
            return 30
        return 29 if is_leap(y) else 28

    def next_date(y, m, d):
        d += 1
        if d > dim(y, m):
            d = 1
            m += 1
            if m > 12:
                m = 1
                y += 1
        return y, m, d

    end = trip["end"]
    end_year = int(end[:4])
    end_month = int(end[5:7])
    end_day = int(end[8:10])

    meal_limits = {}
    dcur = (year, month_num, day)
    while True:
        key = "%04d-%02d-%02d" % dcur
        meal_limits[key] = allowances["meals_per_day"]
        if dcur == (end_year, end_month, end_day):
            break
        dcur = next_date(dcur[0], dcur[1], dcur[2])

    meal_spent = {}
    total = 0.0

    for receipt in receipts:
        note = receipt.get("note", "")
        if "alcohol" in note.lower():
            continue

        amount = float(receipt.get("amount", 0.0))
        currency = receipt.get("currency", "USD")
        date = receipt.get("date", "")

        usd = amount if currency == "USD" else amount * rate_table[currency]

        category = receipt.get("category", "")
        if category == "meal":
            cap = meal_limits.get(date, allowances["meals_per_day"])
            used = meal_spent.get(date, 0.0)
            room = cap - used
            if room > 0:
                take = usd if usd < room else room
                meal_spent[date] = used + take
                total += take
        elif category == "hotel":
            total += usd if usd < allowances["hotel_per_night"] else allowances["hotel_per_night"]
        elif category == "taxi":
            if usd <= 40.0 or note.strip():
                total += usd

    return {"total_usd": round(total, 2)}
