def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(t: str) -> int:
        p = t.split(":")
        return int(p[0]) * 60 + int(p[1])

    def to_time(m: int) -> str:
        h = m // 60
        mm = m % 60
        return ("0" + str(h) if h < 10 else str(h)) + ":" + ("0" + str(mm) if mm < 10 else str(mm))

    def norm_day(d: str) -> str:
        x = d.strip().lower()
        if len(x) >= 3:
            x = x[:3]
        if x == "monday":
            return "mon"
        if x == "tuesday":
            return "tue"
        if x == "wednesday":
            return "wed"
        if x == "thursday":
            return "thu"
        if x == "friday":
            return "fri"
        return x

    def busy_intervals(calendar_day: dict) -> list:
        events = calendar_day.get("events", [])
        out = []
        for e in events:
            if e.get("show_as") == "busy":
                out.append((to_minutes(e["start"]), to_minutes(e["end"])))
        return out

    def is_free_at(starts: list, start_m: int, end_m: int) -> bool:
        for a, b in starts:
            if start_m < b and end_m > a:
                return False
        return True

    day_list = []
    for d in days:
        nd = norm_day(d)
        if nd not in day_list:
            day_list.append(nd)

    starts_by_day = {}
    all_people = [""]
    for a in attendees:
        all_people.append(a)

    for day in day_list:
        calendars = []
        for person in all_people:
            cal = api.read_calendar(person, day)
            if isinstance(cal, dict) and "days" in cal:
                calendars.append(cal)
        if not calendars:
            continue

        user_cal = calendars[0]
        wh = user_cal.get("working_hours", "09:00-17:00").split("-")
        day_start = to_minutes(wh[0])
        day_end = to_minutes(wh[1])
        if earliest != "":
            day_start = max(day_start, to_minutes(earliest))
        if latest_end != "":
            day_end = min(day_end, to_minutes(latest_end) - minutes)

        slot_starts = []
        t = day_start
        if t % 15 != 0:
            t += 15 - (t % 15)

        person_busy = []
        for cal in calendars:
            person_busy.append(busy_intervals(cal["days"][0]))

        while t + minutes <= day_end + minutes:
            ok = True
            for busy in person_busy:
                if not is_free_at(busy, t, t + minutes):
                    ok = False
                    break
            if ok:
                slot_starts.append(to_time(t))
            t += 15

        if slot_starts:
            starts_by_day[day] = slot_starts

    return {"starts": starts_by_day}
