def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def _to_minutes(t: str) -> int:
        if not t:
            return -1
        p = t.split(":")
        return int(p[0]) * 60 + int(p[1])

    def _to_time(m: int) -> str:
        h = m // 60
        mm = m % 60
        return (("0" if h < 10 else "") + str(h) + ":" + ("0" if mm < 10 else "") + str(mm))

    def _norm_day(d: str) -> str:
        s = d.strip().lower()
        if len(s) >= 3:
            s = s[:3]
        return s

    def _overlap(a1: int, a2: int, b1: int, b2: int) -> bool:
        return a1 < b2 and b1 < a2

    def _merge_busy(events: list[dict]) -> list[tuple]:
        intervals = []
        for e in events:
            if e.get("show_as") == "busy":
                intervals.append((_to_minutes(e.get("start", "")), _to_minutes(e.get("end", ""))))
        intervals = sorted(intervals)
        merged = []
        for s, e in intervals:
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            else:
