                user_events = item.get("events", [])
                break

        all_busy = []
        all_busy.append(_merge_busy(user_events))

        person_idx = 1
        for person in people:
            cal = calendars[person_idx]
            person_idx += 1
            p_off_s = cal.get("utc_offset", "-04:00")
            p_off = int(p_off_s[:3]) * 60 + int(p_off_s[4:6])
            diff = p_off - user_off
            p_events = []
