                    p_events = item.get("events", [])
                    break
            busy = _merge_busy(p_events)
            converted = []
            for s, e in busy:
                converted.append((s - diff, e - diff))
            all_busy.append(converted)

        working_start = 9 * 60
        working_end = 17 * 60

        valid = []
        t = earliest_m
        if t % 15 != 0:
            t += 15 - (t % 15)
        while t + minutes <= latest_m:
            ok = True
            if t < working_start or t + minutes > working_end:
                ok = False
            if ok:
                for busy_list in all_busy:
                    for s, e in busy_list:
                        if _overlap(t, t + minutes, s, e):
                            ok = False
                            break
                    if not ok:
                        break
            if ok:
                valid.append(_to_time(t))
            t += 15

        if starts is None:
            starts = set(valid)
        else:
            starts = starts.intersection(set(valid))

    if starts is None:
        starts = set()

    return {"starts": sorted(list(starts))}
