def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_min(t):
        if not t:
            return None
        p = t.split(":")
        return int(p[0]) * 60 + int(p[1])

    def to_str(m):
        h = m // 60
        mm = m % 60
        s = str(h)
        if h < 10:
            s = "0" + s
        if mm < 10:
            return s + ":0" + str(mm)
        return s + ":" + str(mm)

    def ceil_q(m):
        if m % 15 == 0:
            return m
        return m + (15 - m % 15)

    def day_key(d):
        s = str(d).strip().lower()
        if len(s) >= 3:
            s = s[:3]
        return s

    def get_calendar(person, day):
        try:
            return api.read_calendar(person, day)
        except Exception:
            return None

    def extract_day_entry(cal, target_day):
        if not isinstance(cal, dict):
            return None
        days_info = cal.get("days")
        if not isinstance(days_info, list):
            return None
        target = day_key(target_day)
        for item in days_info:
            if isinstance(item, dict) and day_key(item.get("day", "")) == target:
                return item
        return None

    def busy_intervals_for(person, day):
        cal = get_calendar(person, day)
        entry = extract_day_entry(cal, day)
        if not isinstance(entry, dict):
            return []
        events = entry.get("events")
        if not isinstance(events, list):
            return []
        intervals = []
        for ev in events:
            if not isinstance(ev, dict):
                continue
            if str(ev.get("show_as", "busy")).lower() == "free":
                continue
            a = to_min(ev.get("start", ""))
            b = to_min(ev.get("end", ""))
            if a is None or b is None:
                continue
            intervals.append((a, b))
        return intervals

    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        i = 1
        while i < len(intervals):
            a, b = intervals[i]
            la, lb = merged[-1]
            if a <= lb:
                if b > lb:
                    merged[-1] = (la, b)
            else:
                merged.append((a, b))
            i += 1
        return merged

    def is_free(start, end, busy):
        for a, b in busy:
            if start < b and end > a:
                return False
        return True

    earliest_m = to_min(earliest)
    latest_end_m = to_min(latest_end)
    step = 15
    candidates = None
    for d in days:
        all_people = [""]
        i = 0
        while i < len(attendees):
            all_people.append(attendees[i])
            i += 1

        busy_all = []
        j = 0
        while j < len(all_people):
            busy_all.extend(busy_intervals_for(all_people[j], d))
            j += 1
        busy_all = merge_intervals(busy_all)

        day_starts = []
        start_min = 0
        end_limit = 24 * 60
        if earliest_m is not None:
            start_min = earliest_m
        if latest_end_m is not None:
            end_limit = latest_end_m - minutes
        start_min = ceil_q(start_min)
        if end_limit < start_min:
            day_starts = []
        else:
            t = start_min
            while t <= end_limit:
                if is_free(t, t + minutes, busy_all):
                    day_starts.append(t)
                t += step

        if candidates is None:
            candidates = day_starts
        else:
            s = set(day_starts)
            candidates = [x for x in candidates if x in s]

        if not candidates:
            return {"starts": []}

    if candidates is None:
        candidates = []

    candidates = sorted(set(candidates))
    return {"starts": [to_str(x) for x in candidates]}
