def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_min(t):
        if not t:
            return None
        s = str(t).strip()
        parts = s.split(":")
        if len(parts) != 2:
            return None
        try:
            h = int(parts[0])
            m = int(parts[1])
        except Exception:
            return None
        return h * 60 + m

    def to_str(m):
        h = m // 60
        mm = m % 60
        return ("0" if h < 10 else "") + str(h) + ":" + ("0" if mm < 10 else "") + str(mm)

    def ceil_q(m):
        r = m % 15
        if r == 0:
            return m
        return m + (15 - r)

    def norm_day(d):
        s = str(d).strip().lower()
        if len(s) >= 3:
            s = s[:3]
        return s

    def get_calendar(person, day):
        try:
            return api.read_calendar(person, day)
        except Exception:
            return None

    def extract_day(cal, day):
        if not isinstance(cal, dict):
            return None
        ds = cal.get("days")
        if not isinstance(ds, list):
            return None
        target = norm_day(day)
        for item in ds:
            if isinstance(item, dict) and norm_day(item.get("day", "")) == target:
                return item
        return None

    def intervals_from_events(cal, day):
        entry = extract_day(cal, day)
        if not isinstance(entry, dict):
            return []
        evs = entry.get("events")
        if not isinstance(evs, list):
            return []
        out = []
        for ev in evs:
            if not isinstance(ev, dict):
                continue
            show_as = str(ev.get("show_as", "busy")).strip().lower()
            if show_as == "free":
                continue
            a = to_min(ev.get("start", ""))
            b = to_min(ev.get("end", ""))
            if a is None or b is None or b <= a:
                continue
            out.append((a, b))
        return out

    def merge(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        i = 1
        while i < len(intervals):
            a, b = intervals[i]
            la, lb = merged[-1]
            if a <= lb:
                if b > lb:
                    merged[-1] = (la, b)
            else:
                merged.append((a, b))
            i += 1
        return merged

    def pad_intervals(intervals, pad):
        out = []
        for a, b in intervals:
            na = a - pad
            nb = b + pad
            if na < 0:
                na = 0
            if nb > 24 * 60:
                nb = 24 * 60
            out.append((na, nb))
        return out

    def free_at(start, end, busy):
        for a, b in busy:
            if start < b and end > a:
                return False
        return True

    def within_working_hours(cal, start, end):
        if not isinstance(cal, dict):
            return True
        wh = cal.get("working_hours", "")
        if not wh or "-" not in str(wh):
            return True
        parts = str(wh).split("-")
        if len(parts) != 2:
            return True
        ws = to_min(parts[0])
        we = to_min(parts[1])
        if ws is None or we is None:
            return True
        return start >= ws and end <= we

    earliest_m = to_min(earliest)
    latest_end_m = to_min(latest_end)
    start_floor = 0 if earliest_m is None else earliest_m
    start_floor = ceil_q(start_floor)
    end_cap = 24 * 60 if latest_end_m is None else latest_end_m - minutes

    all_people = [""]
    for a in attendees:
        all_people.append(a)

    candidates = None

    for d in days:
        per_person_cals = []
        combined_busy = []
        for p in all_people:
            cal = get_calendar(p, d)
            per_person_cals.append((p, cal))
            combined_busy.extend(intervals_from_events(cal, d))

        combined_busy = merge(combined_busy)

        has_dana = False
        for a in attendees:
            if str(a).strip().lower() == "dana park":
                has_dana = True
                break
        if has_dana:
            combined_busy = merge(pad_intervals(combined_busy, 15))

        day_starts = []
        if end_cap >= start_floor:
            t = start_floor
            while t <= end_cap:
                ok = True
                for p, cal in per_person_cals:
                    if not within_working_hours(cal, t, t + minutes):
                        ok = False
                        break
                if ok and free_at(t, t + minutes, combined_busy):
                    day_starts.append(t)
                t += 15

        if candidates is None:
            candidates = day_starts
        else:
            s = set(day_starts)
            candidates = [x for x in candidates if x in s]

        if not candidates:
            return {"starts": []}

    if candidates is None:
        candidates = []

    candidates = sorted(set(candidates))
    return {"starts": [to_str(x) for x in candidates]}
