def parse_invoice(api, doc_id: str) -> dict:
    text = api.read_document(doc_id).get("text", "")
    lines = [line.strip() for line in text.split("\n") if line.strip() != ""]

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal_usd = 0.0
    freight_usd = 0.0
    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    for line in lines:
        low = line.lower()

        if invoice_number == "" and ("invoice no:" in low or "invoice number:" in low):
            if ":" in line:
                invoice_number = line.split(":", 1)[1].strip()

        if po_number == "" and ("po number:" in low or "po no:" in low or "purchase order:" in low):
            if ":" in line:
                po_number = line.split(":", 1)[1].strip()

        if invoice_date == "" and "invoice date:" in low:
            if ":" in line:
                invoice_date = line.split(":", 1)[1].strip()

        if low.startswith("subtotal:"):
            subtotal_usd = float(line.split(":", 1)[1].strip().replace(",", ""))
        elif low.startswith("freight:"):
            freight_usd = float(line.split(":", 1)[1].strip().replace(",", ""))
        elif low.startswith("terms:"):
            terms = line.split(":", 1)[1].strip().lower()
            if "net" in terms:
                parts = terms.split()
                for i, part in enumerate(parts):
                    if "net" == part and i + 1 < len(parts):
                        try_part = parts[i + 1]
                        if try_part.isdigit():
                            net_days = int(try_part)
                if "/" in terms:
                    left = terms.split("net", 1)[0].strip()
                    if "/" in left:
                        a, b = left.split("/", 1)
                        if a.strip().isdigit():
                            discount_percent = int(a.strip())
                        if b.strip().isdigit():
                            discount_days = int(b.strip())

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": round(subtotal_usd, 2),
        "freight_usd": round(freight_usd, 2),
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }
