def parse_invoice(api, doc_id: str) -> dict:
    doc = api.read_document(doc_id)
    text = doc["text"]

    def find_first(patterns):
        for p in patterns:
            i = text.find(p)
            if i != -1:
                return i, p
        return -1, ""

    def extract_after(labels):
        pos, lab = find_first(labels)
        if pos == -1:
            return ""
        s = text[pos + len(lab):]
        if s[:1] in [":", " "]:
            s = s[1:]
        return s.strip()

    def take_token(s):
        s = s.strip()
        if not s:
            return ""
        parts = s.replace("|", " ").split()
        return parts[0] if parts else ""

    def find_date():
        months = {
            "January": "01", "February": "02", "March": "03", "April": "04",
            "May": "05", "June": "06", "July": "07", "August": "08",
            "September": "09", "October": "10", "November": "11", "December": "12",
        }
        for m in months:
            i = text.find(m)
            if i != -1:
                s = text[i:]
                parts = s.replace(",", "").split()
                if len(parts) >= 3:
                    day = parts[1]
                    if len(day) == 1:
                        day = "0" + day
                    return parts[2] + "-" + months[m] + "-" + day
        for line in text.split("\n"):
            for sep in ["-", "/"]:
                if line.count(sep) >= 2:
                    parts = line.replace(",", "").split()
                    for part in parts:
                        if part.count(sep) == 2:
                            x = part.split(sep)
                            if len(x[0]) == 4:
                                return x[0] + "-" + x[1].zfill(2) + "-" + x[2].zfill(2)
                            if len(x[2]) == 4:
                                return x[2] + "-" + x[1].zfill(2) + "-" + x[0].zfill(2)
        return ""

    invoice_number = ""
    for lab in ["INVOICE", "Invoice", "invoice"]:
        i = text.find(lab)
        if i != -1:
            after = text[i + len(lab):].strip()
            tok = take_token(after)
            if tok and tok.upper() != "NO" and tok.upper() != "NUMBER":
                invoice_number = tok
                break
            parts = after.replace("No.", " ").replace("NO.", " ").replace("No", " ").replace("number", " ").split()
            if parts:
                invoice_number = parts[0]
                break

    po_number = ""
    for lab in ["Customer PO", "PO", "P.O.", "P/O"]:
        i = text.find(lab)
        if i != -1:
            after = text[i + len(lab):].strip()
            tok = take_token(after)
            if tok:
                po_number = tok
                break

    invoice_date = find_date()

    subtotal_usd = 0.0
    freight_usd = 0.0

    for line in text.split("\n"):
        low = line.lower()
        if "goods total" in low or "subtotal" in low or "net goods" in low:
            for part in line.replace(",", "").replace("|", " ").split():
                try:
                    subtotal_usd = float(part)
                except:
                    pass
        if "delivery charge" in low or "freight" in low or "shipping" in low:
            for part in line.replace(",", "").replace("|", " ").split():
                try:
                    freight_usd = float(part)
                except:
                    pass

    if subtotal_usd == 0.0:
        lines = text.split("\n")
        for idx, line in enumerate(lines):
            if "Line total" in line or "line total" in line:
                j = idx + 1
                totals = []
                while j < len(lines):
                    ln = lines[j]
                    if "+" in ln and "-" in ln:
                        j += 1
                        continue
                    if "|" in ln:
                        parts = ln.split("|")
                        if len(parts) >= 5:
                            val = parts[4].replace(",", "").strip()
                            try:
                                totals.append(float(val))
                            except:
                                pass
                    j += 1
                if totals:
                    subtotal_usd = round(sum(totals), 2)
                break

    discount_percent = 0
    discount_days = 0
    net_days = 0

    for line in text.split("\n"):
        low = line.lower()
        if "discount" in low and "%" in low:
            for part in line.replace("%", " ").replace(",", "").split():
                try:
                    discount_percent = float(part)
                except:
                    pass
        if "discount" in low and ("days" in low or "day" in low):
            nums = []
            for part in line.replace(",", "").split():
                try:
                    nums.append(int(float(part)))
                except:
                    pass
            if nums:
                if discount_days == 0:
                    discount_days = nums[0]
                if len(nums) > 1:
                    net_days = nums[-1]
        if "net" in low and "days" in low:
            for part in line.replace(",", "").split():
                try:
                    net_days = int(float(part))
                except:
                    pass
        if "payment terms" in low and "net" in low:
            for part in line.replace(",", "").split():
                if part.lower() == "net":
                    continue
                try:
                    net_days = int(float(part))
                except:
                    pass

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": round(subtotal_usd, 2),
        "freight_usd": round(freight_usd, 2),
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }
