    net_days = 0

    def find_after(markers, end_chars=None):
        for marker in markers:
            i = text.find(marker)
            if i != -1:
                i = i + len(marker)
                while i < len(text) and text[i] == " ":
                    i += 1
                j = i
                while j < len(text):
                    if end_chars is not None and text[j] in end_chars:
                        break
                    j += 1
                return text[i:j].strip()
        return ""

    def parse_money(s):
        s = s.strip()
        if s.startswith("$"):
            s = s[1:]
        if s.endswith("."):
            s = s[:-1]
        return float(s)

    def parse_int_from_text(s):
        n = ""
        for ch in s:
            if ch.isdigit():
                n += ch
            elif n:
                break
        return int(n) if n else 0

    def parse_date_long(s):
        months = {
            "january": "01", "february": "02", "march": "03", "april": "04",
            "may": "05", "june": "06", "july": "07", "august": "08",
            "september": "09", "october": "10", "november": "11", "december": "12"
        }
        parts = s.replace(",", "").split()
        if len(parts) >= 3:
            day = parts[0]
            month = months.get(parts[1].lower(), "01")
            year = parts[2]
            if len(day) == 1:
                day = "0" + day
            return year + "-" + month + "-" + day
        return ""

    po_number = find_after(["PO ", "PO:", "PO#", "PO-", "PO "], end_chars=[".", ",", "\n"])
    if not po_number:
        i = text.find(" PO-")
        if i != -1:
            j = i + 1
            while j < len(text) and text[j] not in [".", ",", "\n", " "]:
                j += 1
            po_number = text[i + 1:j].strip()

    invoice_number = find_after(["invoice ", "invoice is ", "invoice number ", "invoice #", "invoice no. ", "invoice no "], end_chars=[".", ",", "\n", " "])
    if not invoice_number:
        i = text.lower().find(" invoice ")
        if i != -1:
            j = i + len(" invoice ")
            while j < len(text) and text[j] not in [".", ",", "\n", " "]:
                j += 1
            invoice_number = text[i + len(" invoice "):j].strip()

    if "dated " in text.lower():
        i = text.lower().find("dated ") + len("dated ")
        j = i
        while j < len(text) and text[j] not in [".", ",", "\n"]:
            j += 1
        invoice_date = parse_date_long(text[i:j].strip())

    lines = text.split("\n")
