        if "within" in lower and "days" in lower and "%" in line:
            p = line.find("%")
            before = line[:p]
            q = before.rfind(" ")
            if q != -1:
                discount_percent = float(before[q:].strip())
            d = line.lower().find("within")
            if d != -1:
                d += len("within")
                while d < len(line) and line[d] == " ":
                    d += 1
                discount_days = parse_int_from_text(line[d:])

        if "net" in lower and "days" in lower:
