    invoice_date = ""
    subtotal_usd = 0.0
    freight_usd = 0.0
    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    def norm(s):
        s = s.lower()
        s = s.replace("\t", " ")
        while "  " in s:
            s = s.replace("  ", " ")
        return s.strip()

    def is_digit_string(s):
        return s != "" and s.isdigit()

    def clean_amount_token(s):
        t = s.strip().replace(",", "").replace("$", "")
        if t.startswith("(") and t.endswith(")"):
            t = "-" + t[1:-1]
        if t.startswith("+"):
            t = t[1:]
        return t

    def parse_money_token(s):
        t = clean_amount_token(s)
        if t == "":
            return None
        i = 0
        if t.startswith("-"):
            i = 1
        if i == len(t):
            return None
        dot_count = 0
        digit_count = 0
        for ch in t[i:]:
            if ch.isdigit():
                digit_count += 1
            elif ch == ".":
                dot_count += 1
            else:
                return None
        if digit_count == 0 or dot_count > 1:
            return None
        try:
            return float(t)
        except Exception:
            return None

    def tokenize(s):
        out = []
        cur = ""
        for ch in s:
            if ch.isalnum() or ch in [".", "/", "-", "%", "#"]:
                cur += ch
            else:
                if cur != "":
                    out.append(cur)
                    cur = ""
        if cur != "":
            out.append(cur)
        return out

    def extract_date(s):
        t = s.strip().strip(",.;")
        if len(t) < 8:
            return ""
        for sep in ["-", "/"]:
            if sep in t:
                parts = t.split(sep)
                if len(parts) == 3:
                    a, b, c = parts[0].strip(), parts[1].strip(), parts[2].strip()
                    if len(a) == 4 and is_digit_string(a) and is_digit_string(b) and is_digit_string(c):
                        if len(b) == 1:
                            b = "0" + b
                        if len(c) == 1:
                            c = "0" + c
                        return a + "-" + b + "-" + c
                    if len(c) == 4 and is_digit_string(a) and is_digit_string(b) and is_digit_string(c):
                        if len(a) == 1:
                            a = "0" + a
                        if len(b) == 1:
                            b = "0" + b
                        return c + "-" + a + "-" + b
        return ""

    def parse_terms_percent(line):
        low = norm(line)
        tokens = tokenize(low)
        for tok in tokens:
            if "%" in tok:
                x = tok.replace("%", "")
                if x.replace(".", "").isdigit():
                    try:
                        return float(x)
                    except Exception:
                        return None
        return None

