        return ""

    def match_field_value(line, field_names):
        low = norm(line)
        for field in field_names:
            if low.startswith(field):
                rest = line[len(line[:len(line)]) - len(line):]
        for field in field_names:
            idx = low.find(field)
            if idx != -1:
                after = line[idx + len(field):].strip(" :-#\t")
                if after != "":
                    return after
        return ""

    def parse_reference(line, labels):
        low = norm(line)
        for label in labels:
            if label in low:
                idx = low.find(label)
                piece = line[idx + len(label):].strip(" :-#\t")
                if piece != "":
                    parts = tokenize(piece)
                    if len(parts) > 0:
                        return parts[0]
