                        if tl in ["invoice", "inv", "invoiceno", "invoicenumber", "invno"]:
                            if i + 1 < len(toks):
                                nxt = toks[i + 1].strip(":-#,.")
                                if nxt != "" and nxt.lower() not in ["date", "terms", "total"]:
                                    val = nxt
                                    break
            if val != "":
                invoice_number = val

        if po_number == "":
            val = ""
            patterns = [
                "po number", "po no", "po #", "po#", "p.o. number", "p.o. no",
                "purchase order", "p/o", "purchase order no"
            ]
            val = match_field_value(line, patterns)
