                    for i, tok in enumerate(toks):
                        tl = tok.lower().replace(".", "")
                        if tl in ["po", "po#", "p/o", "purchase", "order"]:
                            if i + 1 < len(toks):
                                nxt = toks[i + 1].strip(":-#,.")
                                if nxt != "" and nxt.lower() not in ["number", "no"]:
                                    val = nxt
                                    break
            if val != "":
