                cur += ch
            else:
                if cur != "":
                    out.append(cur)
                    cur = ""
        if cur != "":
            out.append(cur)
        return out

    def extract_date(s):
        t = s.strip().strip(",.;:")
        if len(t) >= 10:
            for sep in ["-", "/"]:
                if sep in t:
                    parts = t.split(sep)
                    if len(parts) == 3:
                        a = parts[0].strip()
                        b = parts[1].strip()
                        c = parts[2].strip()
                        if len(a) == 4 and is_digits(a) and is_digits(b) and is_digits(c):
                            if len(b) == 1:
                                b = "0" + b
                            if len(c) == 1:
                                c = "0" + c
                            return a + "-" + b + "-" + c
                        if len(c) == 4 and is_digits(a) and is_digits(b) and is_digits(c):
                            if len(a) == 1:
                                a = "0" + a
                            if len(b) == 1:
                                b = "0" + b
                            return c + "-" + a + "-" + b
        return ""

    def looks_like_date_token(tok):
        return extract_date(tok) != ""

    def parse_percent_token(tok):
        t = tok.replace("%", "")
        if t == "":
            return None
        ok = True
        for ch in t:
            if not (ch.isdigit() or ch == "."):
                ok = False
                break
        if not ok:
