            for piece in low.replace("days", "").replace("day", "").split():
                if "/" in piece:
                    ab = piece.split("/")
                    if len(ab) == 2:
                        a = "".join([ch for ch in ab[0] if ch.isdigit()])
                        b = "".join([ch for ch in ab[1] if ch.isdigit()])
                        if a != "":
                            dd = int(a)
                        if b != "":
                            nd = int(b)

