    def amount_candidates(line):
        vals = line_amounts(line)
        out = []
        for v in vals:
            out.append(v)
        return out

    def find_summary_amount(lines, label_groups):
        for line in lines:
            low = norm(line)
            if has_label(line, label_groups):
                vals = amount_candidates(line)
                if len(vals) > 0:
                    return vals[-1]
        return None

    def compute_subtotal_from_items(lines):
        item_amounts = []
        started = False
        for line in lines:
            low = norm(line)
            if has_label(line, ["item", "description", "qty", "quantity", "price", "unit", "amount"]):
