def parse_invoice(api, doc_id: str) -> dict:
    """Read a vendor invoice document, in whatever layout its vendor uses, and extract what the ledger records."""
    try:
        doc = api.read_document(doc_id)
        if isinstance(doc, str):
            text = doc
        elif isinstance(doc, dict):
            text = doc.get("text", "")
        else:
            text = str(doc)
    except Exception:
        return {"doc_id": doc_id}

    text = text.replace("\r", "\n")
    lines = text.split("\n")
    lowtext = text.lower()

    months = {
        "january": "01", "february": "02", "march": "03", "april": "04",
        "may": "05", "june": "06", "july": "07", "august": "08",
        "september": "09", "october": "10", "november": "11", "december": "12"
    }

    def clean_money(s):
        s = s.strip().replace(",", "")
        if s.startswith("$"):
            s = s[1:].strip()
        if s.endswith("."):
            s = s[:-1]
        return s

    def to_float(s):
        try:
            return float(clean_money(s))
        except Exception:
            return 0.0

    def parse_date(s):
        s = s.strip().replace(",", "")
        if not s:
            return ""
        if len(s) >= 10 and s[4] == "-" and s[7] == "-":
            return s[:10]
        if len(s) >= 10 and s[2] == "/" and s[5] == "/":
            a, b, c = s[:10].split("/")
            if len(a) == 4:
                return a + "-" + b.zfill(2) + "-" + c.zfill(2)
            return c + "-" + a.zfill(2) + "-" + b.zfill(2)
        parts = s.split()
        if len(parts) >= 3 and parts[0].lower() in months:
            d = parts[1]
            if d.endswith(("st", "nd", "rd", "th")):
                d = d[:-2]
            if d.isdigit():
                d = d.zfill(2)
            return parts[2] + "-" + months[parts[0].lower()] + "-" + d
        if len(parts) >= 3 and parts[1].lower() in months:
            d = parts[0]
            if d.endswith(("st", "nd", "rd", "th")):
                d = d[:-2]
            if d.isdigit():
                d = d.zfill(2)
            return parts[2] + "-" + months[parts[1].lower()] + "-" + d
        return s[:10]

    def strip_punct(s):
        return s.strip().strip(".,;|")

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal_usd = 0.0
    freight_usd = 0.0
    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    for line in lines:
        t = line.strip()
        low = t.lower()

        if not invoice_number:
            if low.startswith("invoice no"):
                if ":" in t:
                    invoice_number = strip_punct(t.split(":", 1)[1])
                else:
                    invoice_number = strip_punct(t.split()[-1])
            elif low.startswith("invoice number"):
                if ":" in t:
                    invoice_number = strip_punct(t.split(":", 1)[1])
            elif low.startswith("invoice ") and len(t.split()) >= 2:
                invoice_number = strip_punct(t.split(None, 1)[1])
            elif ";invoice;" in low:
                parts = [p.strip() for p in t.split(";")]
                if len(parts) >= 3:
                    invoice_number = strip_punct(parts[2])

        if not po_number:
            if "po number" in low:
                if ":" in t:
                    po_number = strip_punct(t.split(":", 1)[1])
                else:
                    po_number = strip_punct(t.split()[-1])
            elif "order ref" in low:
                if ":" in t:
                    po_number = strip_punct(t.split(":", 1)[1])
                elif ";" in t:
                    parts = [p.strip() for p in t.split(";")]
                    if len(parts) >= 2:
                        po_number = strip_punct(parts[1])
            elif "customer po" in low:
                idx = low.find("customer po")
                tail = t[idx + len("customer po"):].replace("|", " ").replace(":", " ")
                po_number = strip_punct(tail.split()[0]) if tail.split() else ""
            elif "thank you for your order" in low and "po-" in low:
                idx = low.find("po-")
                po_number = strip_punct(t[idx:].split()[0])

        if not invoice_date:
            if low.startswith("invoice date"):
                if ":" in t:
                    invoice_date = parse_date(t.split(":", 1)[1])
                else:
                    invoice_date = parse_date(t.split()[-1])
            elif low.startswith("date;"):
                parts = [p.strip() for p in t.split(";")]
                if len(parts) >= 2:
                    invoice_date = parse_date(parts[1])
            elif low.startswith("date:"):
                invoice_date = parse_date(t.split(":", 1)[1])
            elif low.startswith("dated "):
                invoice_date = parse_date(t[6:].split("|")[0])
            elif " dated " in low and "invoice" in low:
                idx = low.find("dated ")
                invoice_date = parse_date(t[idx + 6:].split("|")[0])

        if "terms" in low or "payment terms" in low:
            s = low.replace("payment terms", "").replace("terms", "").strip()
            if "2/10" in s:
                discount_percent = 2.0
                discount_days = 10
            elif "1/10" in s:
                discount_percent = 1.0
                discount_days = 10
            elif "1.5" in s:
                discount_percent = 1.5
                discount_days = 15

            if "net 45" in s or "n45" in s:
                net_days = 45
            elif "net 30" in s or "n30" in s:
                net_days = 30
            elif "30 days" in s:
                net_days = 30

        if freight_usd == 0.0:
            if "freight:" in low:
                freight_usd = to_float(t.split(":", 1)[1] if ":" in t else t)
            elif "delivery charge" in low:
                idx = low.find("delivery charge")
                freight_usd = to_float(t[idx + len("delivery charge"):])
            elif "carriage" in low:
                idx = low.find("carriage")
                freight_usd = to_float(t[idx + len("carriage"):])
            elif "shipping" in low:
                if ";" in t:
                    parts = [p.strip() for p in t.split(";")]
                    for p in parts:
                        if "shipping" in p.lower():
                            freight_usd = to_float(p)
                            break
                else:
                    idx = low.find("shipping")
                    freight_usd = to_float(t[idx + len("shipping"):])

    if not invoice_number:
        if "invoice no" in lowtext:
            idx = lowtext.find("invoice no")
            tail = text[idx:]
            if ":" in tail:
                invoice_number = strip_punct(tail.split(":", 1)[1].split()[0])
        elif "invoice number" in lowtext:
            idx = lowtext.find("invoice number")
            tail = text[idx:]
            if ":" in tail:
                invoice_number = strip_punct(tail.split(":", 1)[1].split()[0])
        elif ";invoice;" in lowtext:
            parts = [p.strip() for p in text.split(";")]
            if len(parts) >= 3:
                invoice_number = strip_punct(parts[2])

    if not po_number:
        for key in ["po number", "order ref", "customer po"]:
            if key in lowtext:
                idx = lowtext.find(key)
                tail = text[idx + len(key):].replace("|", " ").replace(":", " ").replace(";", " ")
                toks = tail.split()
                if toks:
                    po_number = strip_punct(toks[0])
                    break
        if not po_number and "po-" in lowtext:
            idx = lowtext.find("po-")
            po_number = strip_punct(text[idx:].split()[0])

    if not invoice_date:
        if "invoice date" in lowtext:
            idx = lowtext.find("invoice date")
            tail = text[idx + len("invoice date"):].replace(":", " ").replace(";", " ")
            toks = tail.split()
            if toks:
                invoice_date = parse_date(" ".join(toks[:3]))
        elif "date;" in lowtext:
            idx = lowtext.find("date;")
            tail = text[idx + len("date;"):].split("\n", 1)[0]
            invoice_date = parse_date(tail)
        elif "dated" in lowtext:
            idx = lowtext.find("dated")
            tail = text[idx + len("dated"):].split("|")[0]
            invoice_date = parse_date(tail)

    subtotal_found = False
    for line in lines:
        t = line.strip()
        low = t.lower()
        if "subtotal" in low or "goods total" in low:
            if ":" in t:
                subtotal_usd = to_float(t.split(":", 1)[1].split("|")[0])
            else:
                toks = t.replace("|", " ").split()
                for tok in reversed(toks):
                    val = to_float(tok)
                    if val != 0.0 or tok.strip("0.") == "":
                        subtotal_usd = val
                        break
            subtotal_found = True
        elif low.startswith("total due") and not subtotal_found:
            pass

    item_total = 0.0
    item_found = False

    for line in lines:
        t = line.strip()
        low = t.lower()

        if "qty" in low and "price" in low and ";" in t:
            parts = [p.strip() for p in t.split(";")]
            if len(parts) >= 4 and parts[0] and parts[0].lower() != "item":
                try:
                    q = float(parts[2])
                    p = float(parts[3])
                    item_total += q * p
                    item_found = True
                except Exception:
                    pass

        if "|" in t and ("qty" in low or "line total" in low):
            parts = [p.strip() for p in t.split("|")]
            if len(parts) >= 5 and parts[0] and parts[0].lower() != "item":
                try:
                    q = float(parts[2].replace(",", ""))
                    price = float(clean_money(parts[3]))
                    item_total += q * price
                    item_found = True
                except Exception:
                    try:
                        line_total = float(clean_money(parts[4]))
                        item_total += line_total
                        item_found = True
                    except Exception:
                        pass

        if "we supplied:" in low:
            tail = t.split(":", 1)[1] if ":" in t else ""
            for seg in tail.split(";"):
                seg = seg.strip()
                if " x " in seg.lower() and " at $" in seg.lower():
                    try:
                        qpart = seg.lower().split(" x ", 1)[0].split()[-1]
                        q = float(qpart)
                        p = float(seg.lower().split(" at $", 1)[1].split()[0])
                        item_total += q * p
                        item_found = True
                    except Exception:
                        pass

        if ";" in t and len(t.split(";")) >= 4:
            parts = [p.strip() for p in t.split(";")]
            if parts[0] and parts[0].upper().startswith(("QM-", "KS-", "MO-", "TD-")):
                try:
                    q = float(parts[2])
                    p = float(parts[3])
                    item_total += q * p
                    item_found = True
                except Exception:
                    pass

        if " at $" in low and " x " in low:
            try:
                left = low.split(" at $", 1)[0]
                q = float(left.split(" x ")[0].split()[-1])
                p = float(low.split(" at $", 1)[1].split()[0].replace(",", ""))
                item_total += q * p
                item_found = True
            except Exception:
                pass

    if item_found:
        subtotal_usd = round(item_total, 2)

    result = {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": round(subtotal_usd, 2),
        "freight_usd": round(freight_usd, 2),
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }

    try:
        api.record_invoice(result)
    except Exception:
        pass

    return result
