def amount_payable(api, invoice_id: str) -> dict:
    invoice = api.read_invoice(invoice_id)
    if not isinstance(invoice, dict):
        raise ValueError("invalid invoice")

    po_number = invoice.get("po_number")
    client_id = invoice.get("client_id")
    invoice_date = invoice.get("invoice_date")
    terms = invoice.get("terms") if isinstance(invoice.get("terms"), dict) else {}
    lines = invoice.get("lines") if isinstance(invoice.get("lines"), list) else []
    freight = invoice.get("freight_usd")
    freight = float(freight) if freight is not None else 0.0

    po = None
    if po_number:
        try:
            po = api.read_purchase_order(po_number)
            if not isinstance(po, dict) or po.get("error"):
                po = None
        except Exception:
            po = None

    if po and po.get("client_id"):
        client_id = po.get("client_id")

    client_terms = api.read_client_terms(client_id)
    if not isinstance(client_terms, dict) or client_terms.get("error"):
        raise ValueError("invalid client terms")

    tax_rate = client_terms.get("sales_tax_rate", 0.0)
    taxed_categories = client_terms.get("taxed_categories", [])
    taxed_categories = taxed_categories if isinstance(taxed_categories, list) else []

    delivered_by_sku = {}
    if po and isinstance(po.get("lines"), list):
        for po_line in po.get("lines"):
            if isinstance(po_line, dict):
                sku = po_line.get("sku")
                if sku is not None:
                    delivered_by_sku[sku] = po_line.get("delivered", 0)

    goods_total = 0.0
    tax_total = 0.0
    for line in lines:
        if not isinstance(line, dict):
            continue
        sku = line.get("sku")
        category = line.get("category")
        qty = line.get("quantity", 0)
        unit_price = line.get("unit_price", 0.0)
        invoiced_qty = int(qty) if qty is not None else 0
        delivered_qty = delivered_by_sku.get(sku, invoiced_qty)
        pay_qty = min(invoiced_qty, delivered_qty)
        line_amount = float(pay_qty) * float(unit_price)
        goods_total += line_amount
        if category in taxed_categories:
            tax_total += line_amount * float(tax_rate)

    discount_percent = float(terms.get("discount_percent", 0.0) or 0.0)
    discount_days = int(terms.get("discount_days", 0) or 0)
    net_days = int(terms.get("net_days", 0) or 0)

    if discount_percent > 0 and discount_days > 0:
        amount = goods_total * (1.0 - discount_percent) + tax_total + freight
        pay_on = _add_days(invoice_date, discount_days)
    else:
        amount = goods_total + tax_total + freight
        pay_on = _add_days(invoice_date, net_days)

    amount = round(amount + 1e-12, 2)
    return api.schedule_payment({"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on})


def _add_days(date_text, days):
    y = int(date_text[0:4])
    m = int(date_text[5:7])
    d = int(date_text[8:10])
    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    if leap(y):
        month_lengths[1] = 29

    d += int(days)
    while d > month_lengths[m - 1]:
        d -= month_lengths[m - 1]
        m += 1
        if m > 12:
            m = 1
            y += 1
            month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            if leap(y):
                month_lengths[1] = 29

    return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)
