    api.schedule_payment({"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on})
    return {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}


def _add_days(date_str, days):
    y = int(date_str[0:4])
    m = int(date_str[5:7])
    d = int(date_str[8:10])

    leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
    mdays = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    d += days
    while d > mdays[m - 1]:
        d -= mdays[m - 1]
        m += 1
        if m > 12:
            m = 1
            y += 1
            leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
            mdays = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    yy = str(y)
    if len(yy) < 4:
        yy = "0" * (4 - len(yy)) + yy
    mm = str(m)
    if len(mm) < 2:
        mm = "0" + mm
    dd = str(d)
    if len(dd) < 2:
        dd = "0" + dd
    return yy + "-" + mm + "-" + dd
