    if not isinstance(tax_rate, (int, float)):
        tax_rate = 0.0
    tax_rate = float(tax_rate)

    exclude_categories = payment_rules.get("exclude_categories", [])
    if not isinstance(exclude_categories, list):
        exclude_categories = [exclude_categories]

    nonpayable_categories = payment_rules.get("nonpayable_categories", [])
    if not isinstance(nonpayable_categories, list):
        nonpayable_categories = [nonpayable_categories]

    freight_payable = False
    freight_taxed = False
    if isinstance(payment_rules.get("freight_payable", False), bool):
        freight_payable = payment_rules.get("freight_payable", False)
    if isinstance(payment_rules.get("freight_taxed", False), bool):
        freight_taxed = payment_rules.get("freight_taxed", False)

    invoice_lines = invoice.get("lines", [])
    if not isinstance(invoice_lines, list):
        invoice_lines = []

    goods_total = 0.0
    tax_total = 0.0

    for line in invoice_lines:
        if not isinstance(line, dict):
            continue

        sku = line.get("sku")
        category = line.get("category")

        if category in exclude_categories:
            continue
        if category in nonpayable_categories:
            continue

        quantity = line.get("quantity", 0.0)
        unit_price = line.get("unit_price", 0.0)
        if not isinstance(quantity, (int, float)):
            quantity = 0.0
        if not isinstance(unit_price, (int, float)):
