            if not isinstance(ordered_qty, (int, float)):
                ordered_qty = quantity
            if not isinstance(delivered_qty, (int, float)):
                delivered_qty = ordered_qty
            payable_qty = min(float(quantity), float(ordered_qty), float(delivered_qty))

        line_total = payable_qty * float(unit_price)
        goods_total += line_total

        if category in taxed_categories:
            tax_total += line_total * tax_rate

