            date_text = "0000-01-01"
        y = int(date_text[0:4])
        m = int(date_text[5:7])
        d = int(date_text[8:10])

        if not isinstance(days, int):
            days = int(days)

        while days > 0:
            leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
            month_lengths = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            remaining = month_lengths[m - 1] - d
            if days <= remaining:
                d += days
                days = 0
            else:
                days -= remaining + 1
                d = 1
                m += 1
                if m > 12:
                    m = 1
                    y += 1

        return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)

    amount = goods_total + tax_total

    vendor_terms = invoice.get("vendor_terms", invoice.get("payment_terms", {}))
    if not isinstance(vendor_terms, dict):
        vendor_terms = {}

    pay_on = None

    due_date = vendor_terms.get("due_date", None)
    due_after_days = vendor_terms.get("due_after_days", None)
    due_from = vendor_terms.get("due_from", None)
    net_days = vendor_terms.get("net_days", vendor_terms.get("due_days", None))

    if due_after_days is not None and isinstance(due_after_days, (int, float)):
        pay_on = add_days(invoice_date, int(due_after_days))
    elif due_from == "invoice_date" and isinstance(net_days, (int, float)):
        pay_on = add_days(invoice_date, int(net_days))
    elif isinstance(net_days, (int, float)):
        pay_on = add_days(invoice_date, int(net_days))
    elif isinstance(due_date, str) and len(due_date) >= 10:
        pay_on = due_date
    else:
        pay_on = add_days(invoice_date, 0)

    discount_percent = payment_rules.get("discount_percent", 0.0)
    discount_days = payment_rules.get("discount_days", 0)
    if isinstance(discount_percent, (int, float)) and isinstance(discount_days, (int, float)):
        if discount_percent > 0 and discount_days > 0:
            early_pay_on = add_days(invoice_date, int(discount_days))
            if due_after_days is None and not (due_from == "invoice_date" and isinstance(net_days, (int, float))) and not isinstance(net_days, (int, float)):
                amount = goods_total * (1.0 - float(discount_percent)) + tax_total
                pay_on = early_pay_on

    amount = round(amount + 1e-12, 2)

    return {
