def amount_payable(api, invoice_id: str) -> dict:
    invoice = api.read_invoice(invoice_id)
    po_number = invoice["po_number"]
    client_id = invoice["client_id"]

    po = api.read_purchase_order(po_number)
    client = api.read_client_terms(client_id)

    delivered_by_sku = {}
    for line in po["lines"]:
        delivered_by_sku[line["sku"]] = line["delivered"]

    taxed_categories = set(client["taxed_categories"])
    tax_rate = client["sales_tax_rate"]

    goods_total = 0.0
    tax_total = 0.0

    for line in invoice["lines"]:
        qty = line["quantity"]
        if line["sku"] in delivered_by_sku:
            qty = min(qty, delivered_by_sku[line["sku"]])
        line_goods = qty * line["unit_price"]
        goods_total += line_goods
        if line["category"] in taxed_categories:
            tax_total += line_goods * tax_rate

    freight = invoice["freight_usd"]

    discount_percent = invoice["terms"]["discount_percent"]
    discount_days = invoice["terms"]["discount_days"]
    net_days = invoice["terms"]["net_days"]

    if discount_percent:
        goods_total = goods_total * (1.0 - discount_percent / 100.0)
        pay_on_days = discount_days
    else:
        pay_on_days = net_days

    amount = round(goods_total + tax_total + freight, 2)

    date_parts = invoice["invoice_date"].split("-")
    year = int(date_parts[0])
    month = int(date_parts[1])
    day = int(date_parts[2])

    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    if is_leap(year):
        month_lengths[1] = 29

    day += pay_on_days
    while True:
        ml = month_lengths[month - 1]
        if day <= ml:
            break
        day -= ml
        month += 1
        if month > 12:
            month = 1
            year += 1
            month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            if is_leap(year):
                month_lengths[1] = 29

    year_s = str(year)
    month_s = str(month)
    day_s = str(day)
    if len(year_s) < 4:
        year_s = "0" * (4 - len(year_s)) + year_s
    if len(month_s) < 2:
        month_s = "0" + month_s
    if len(day_s) < 2:
        day_s = "0" + day_s
    pay_on = year_s + "-" + month_s + "-" + day_s

    result = {
        "invoice_id": invoice_id,
        "amount_usd": amount,
        "pay_on": pay_on
    }

    if hasattr(api, "schedule_payment"):
        try:
            api.schedule_payment(invoice_id, amount, pay_on)
        except TypeError:
            try:
                api.schedule_payment(result)
            except Exception:
                pass

    return result
