def amount_payable(api, invoice_id: str) -> dict:
    def is_leap_year(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def add_days(date_str, days):
        if not isinstance(date_str, str) or len(date_str) < 10:
            return date_str
        y = int(date_str[0:4])
        m = int(date_str[5:7])
        d = int(date_str[8:10]) + int(days)
        mdays_list = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        while True:
            mdays = mdays_list[m - 1]
            if m == 2 and is_leap_year(y):
                mdays = 29
            if d <= mdays:
                break
            d -= mdays
            m += 1
            if m > 12:
                m = 1
                y += 1
        return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)

    def safe_float(v, default=0.0):
        try:
            return float(v)
        except Exception:
            return default

    def safe_int(v, default=0):
        try:
            return int(v)
        except Exception:
            return default

    invoice = api.read_invoice(invoice_id)
    if not isinstance(invoice, dict):
        return invoice
    if "error" in invoice:
        return invoice

    client_id = invoice.get("client_id", invoice.get("client"))
    client = {}
    if client_id is not None:
        try:
            client = api.read_client_terms(client_id)
        except Exception:
            client = {}
        if not isinstance(client, dict) or "error" in client:
            client = {}

    po_number = invoice.get("po_number", invoice.get("purchase_order"))
    po = {}
    if po_number is not None:
        try:
            po = api.read_purchase_order(po_number)
        except Exception:
            po = {}
        if not isinstance(po, dict) or "error" in po:
            po = {}

    delivered_map = {}
    for line in po.get("lines", []):
        if isinstance(line, dict):
            sku = line.get("sku")
            if sku is not None:
                delivered_map[sku] = line.get("quantity_delivered", line.get("delivered", line.get("quantity", 0)))

    sales_tax_rate = safe_float(client.get("sales_tax_rate", 0.0), 0.0)
    taxed_categories = client.get("taxed_categories", [])
    if not isinstance(taxed_categories, list):
        taxed_categories = []

    payment_rules = client.get("payment_rules", {})
    if not isinstance(payment_rules, dict):
        payment_rules = {}

    pay_goods = 0.0
    tax_base = 0.0
    freight = safe_float(invoice.get("freight_usd", invoice.get("freight", 0.0)), 0.0)

    lines = invoice.get("lines", [])
    if not isinstance(lines, list):
        lines = []

    for line in lines:
        if not isinstance(line, dict):
            continue
        sku = line.get("sku")
        qty_invoiced = safe_float(line.get("quantity", 0.0), 0.0)
        qty_delivered = delivered_map.get(sku, qty_invoiced)
        if qty_delivered is None:
            qty_delivered = qty_invoiced
        qty_delivered = safe_float(qty_delivered, qty_invoiced)
        qty = min(qty_invoiced, qty_delivered)
        unit_price = safe_float(line.get("unit_price", 0.0), 0.0)
        line_amount = qty * unit_price
        pay_goods += line_amount
        if line.get("category") in taxed_categories:
            tax_base += line_amount

    amount = pay_goods + round(tax_base * sales_tax_rate, 2) + freight

    terms = invoice.get("terms", {})
    if not isinstance(terms, dict):
        terms = invoice.get("vendor_terms", {})
        if not isinstance(terms, dict):
            terms = {}

    discount_percent = safe_float(terms.get("discount_percent", 0.0), 0.0)
    discount_days = safe_int(terms.get("discount_days", 0), 0)
    net_days = safe_int(terms.get("net_days", 0), 0)

    if discount_percent:
        amount -= round(pay_goods * discount_percent / 100.0, 2)

    client_name = client.get("name", "")
    if not isinstance(client_name, str):
        client_name = ""

    if client_name == "Alder & Finch Clinics":
        amount -= freight

    if client_name == "Copperline Builders":
        for line in lines:
            if isinstance(line, dict):
                if line.get("category") in ["construction materials", "materials"]:
                    amount *= 0.95
                    break

    amount = round(amount, 2)

    if client_name == "Bramblewood Schools":
        amount = float(int(round(amount, 0)))

    invoice_date = str(invoice.get("invoice_date", invoice.get("date", "")))

    pay_on = invoice_date

    if "pay_by_date" in payment_rules:
        pay_on = str(payment_rules.get("pay_by_date", invoice_date))
    elif "pay_by_days" in payment_rules:
        pay_on = add_days(invoice_date, safe_int(payment_rules.get("pay_by_days", 0), 0))
    elif "days_after_invoice" in payment_rules:
        pay_on = add_days(invoice_date, safe_int(payment_rules.get("days_after_invoice", 0), 0))
    elif "days_after_end_of_month" in payment_rules:
        n = safe_int(payment_rules.get("days_after_end_of_month", 0), 0)
        if isinstance(invoice_date, str) and len(invoice_date) >= 10:
            y = int(invoice_date[0:4])
            m = int(invoice_date[5:7])
            mdays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
            if m == 2 and is_leap_year(y):
                mdays = 29
            eom = str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(mdays).zfill(2)
            pay_on = add_days(eom, n)
    elif discount_percent and discount_days:
        pay_on = add_days(invoice_date, discount_days)
    elif net_days:
        pay_on = add_days(invoice_date, net_days)
    elif "pay_by_date" in terms:
        pay_on = str(terms.get("pay_by_date", invoice_date))
    elif "pay_by_days" in terms:
        pay_on = add_days(invoice_date, safe_int(terms.get("pay_by_days", 0), 0))
    elif "days" in terms:
        pay_on = add_days(invoice_date, safe_int(terms.get("days", 0), 0))
    elif "due_date" in terms:
        pay_on = str(terms.get("due_date", invoice_date))

    payload = {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}
    try:
        return api.schedule_payment(payload)
    except Exception:
        return payload
