def parse_invoice(api, doc_id: str) -> dict:
    text = ""
    reader = None

    if isinstance(api, dict):
        try:
            reader = api["read_document"]
        except Exception:
            reader = None
    else:
        try:
            reader = api.read_document
        except Exception:
            reader = None

    if reader:
        try:
            try:
                doc = reader(doc_id)
            except Exception:
                doc = reader({"doc_id": doc_id})
            if isinstance(doc, dict):
                text = doc.get("text", "")
        except Exception:
            text = ""

    if not text:
        return {
            "doc_id": doc_id,
            "invoice_number": "",
            "po_number": "",
            "invoice_date": "",
            "subtotal_usd": 0.0,
            "freight_usd": 0.0,
            "discount_percent": 0.0,
            "discount_days": 0,
            "net_days": 0
        }

    lines = text.split("\n")
    full = "\n".join(lines)

    def parse_date(s):
        s = s.strip().strip(".")
        if len(s) >= 10 and s[4] == "-" and s[7] == "-":
            return s[:10]
        if len(s) >= 10 and s[2] == "/" and s[5] == "/":
            m = s[:2]
            d = s[3:5]
            y = s[6:10]
            if m.isdigit() and d.isdigit() and y.isdigit():
                return y + "-" + m.zfill(2) + "-" + d.zfill(2)
        months = {
            "january": "01", "february": "02", "march": "03", "april": "04",
            "may": "05", "june": "06", "july": "07", "august": "08",
            "september": "09", "october": "10", "november": "11", "december": "12"
        }
        parts = s.replace(",", "").split()
        if len(parts) >= 3:
            a = parts[0]
            b = parts[1]
            c = parts[2]
            if a.isdigit() and b.lower() in months and c.isdigit():
                return c + "-" + months[b.lower()] + "-" + a.zfill(2)
            if b.lower() in months and a.isdigit() and c.isdigit():
                return c + "-" + months[b.lower()] + "-" + a.zfill(2)
        return ""

    def money_to_float(s):
        out = ""
        for ch in s:
            if ch.isdigit() or ch == "." or ch == "-":
                out += ch
        try:
            return float(out)
        except Exception:
            return 0.0

    def first_po(s):
        parts = s.replace(",", " ").replace(";", " ").replace("|", " ").split()
        for p in parts:
            if p.startswith("PO-"):
                return p.strip(".,")
        return ""

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal_usd = 0.0
    freight_usd = 0.0
    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    for line in lines:
        s = line.strip()
        low = s.lower()

        if not invoice_number:
            if "invoice no" in low:
                if ":" in s:
                    invoice_number = s.split(":", 1)[1].strip()
                elif ";" in s:
                    parts = [p.strip() for p in s.split(";")]
                    if len(parts) >= 3:
                        invoice_number = parts[2]
                else:
                    parts = s.split()
                    if len(parts) >= 2:
                        invoice_number = parts[-1]
            elif low.startswith("invoice ") and ";" in s:
                parts = [p.strip() for p in s.split(";")]
                if len(parts) >= 3:
                    invoice_number = parts[2]
            elif low.startswith("invoice ") and ":" not in s and ";" not in s:
                parts = s.split()
                if len(parts) >= 2:
                    invoice_number = parts[-1]
            elif "this letter is our invoice" in low:
                tail = s.split("invoice", 1)[1].strip()
                if "," in tail:
                    tail = tail.split(",", 1)[0].strip()
                if "dated" in tail.lower():
                    tail = tail.split("dated", 1)[0].strip()
                invoice_number = tail
            elif low.startswith("invoice;"):
                parts = [p.strip() for p in s.split(";")]
                if len(parts) >= 3:
                    invoice_number = parts[2]

        if not po_number:
            if "po number" in low:
                if ":" in s:
                    po_number = s.split(":", 1)[1].strip()
            elif "order ref" in low:
                po_number = first_po(s)
            elif "customer po" in low:
                po_number = first_po(s)
            elif "thank you for your order" in low:
                po_number = first_po(s)
            elif "po-" in low:
                po_number = first_po(s)

        if not invoice_date:
            if "invoice date:" in low:
                invoice_date = s.split(":", 1)[1].strip()
            elif low.startswith("date;"):
                invoice_date = s.split(";", 1)[1].strip()
            elif low.startswith("date:"):
                invoice_date = s.split(":", 1)[1].strip()
            elif "dated" in low:
                idx = low.find("dated")
                invoice_date = s[idx + 5:].strip().strip(".")
                if "|" in invoice_date:
                    invoice_date = invoice_date.split("|", 1)[0].strip()

        if "terms" in low or "payment terms" in low:
            if "1/10" in low:
                discount_percent = 1.0
                discount_days = 10
            elif "2/10" in low:
                discount_percent = 2.0
                discount_days = 10
            elif "1.5%" in low:
                discount_percent = 1.5
                discount_days = 15
            elif "1.5" in low and "discount" in low:
                discount_percent = 1.5
                discount_days = 15
            if "net 45" in low:
                net_days = 45
            elif "net 30" in low or "n30" in low:
                net_days = 30

        if "subtotal" in low or "goods total" in low:
            if "subtotal" in low:
                subtotal_usd = money_to_float(s.split("subtotal", 1)[1])
            elif "goods total" in low:
                subtotal_usd = money_to_float(s.split("goods total", 1)[1])

        if "freight" in low or "delivery charge" in low or "shipping" in low or "carriage" in low:
            if ":" in s:
                freight_usd = money_to_float(s.split(":", 1)[1])
            else:
                freight_usd = money_to_float(s)

    if not invoice_date:
        for line in lines:
            s = line.strip()
            low = s.lower()
            if "dated" in low:
                invoice_date = parse_date(s.split("dated", 1)[1].strip().strip("."))
                if invoice_date:
                    break
            if low.startswith("date;"):
                invoice_date = parse_date(s.split(";", 1)[1].strip())
                if invoice_date:
                    break
            if low.startswith("date:"):
                invoice_date = parse_date(s.split(":", 1)[1].strip())
                if invoice_date:
                    break
            if "invoice date:" in low:
                invoice_date = parse_date(s.split(":", 1)[1].strip())
                if invoice_date:
                    break

    invoice_date = parse_date(invoice_date) if invoice_date else ""

    if not net_days:
        lowfull = full.lower()
        if "net 45" in lowfull:
            net_days = 45
        elif "net 30" in lowfull or "n30" in lowfull:
            net_days = 30

    total = 0.0
    item_lines = 0

    for line in lines:
        s = line.strip()
        low = s.lower()

        if ";" in s:
            parts = [p.strip() for p in s.split(";")]
            if len(parts) >= 4 and parts[0] and parts[0].lower() not in ["invoice", "date", "order ref", "terms", "item", "description", "qty", "price", "shipping", "date", "invoice no"]:
                try:
                    qty = float(parts[2].replace(",", ""))
                    price = float(parts[3].replace(",", ""))
                    total += qty * price
                    item_lines += 1
                except Exception:
                    pass

        elif "|" in s and not s.startswith("+") and "qty" not in low:
            parts = [p.strip() for p in s.split("|")]
            if len(parts) >= 5 and parts[0] and parts[0].lower() not in ["item", "sku", "description"]:
                try:
                    qty = float(parts[2].replace(",", ""))
                    price = float(parts[3].replace(",", ""))
                    total += qty * price
                    item_lines += 1
                except Exception:
                    pass

        elif " x " in s.lower() and " at $" in low:
            pieces = s.replace(";", " ").split(" at $")
            left = pieces[0]
            right = pieces[1] if len(pieces) > 1 else ""
            try:
                qty = float(left.lower().split(" x ", 1)[0].strip().split()[-1].replace(",", ""))
                price = float(right.split()[0].replace(",", ""))
                total += qty * price
                item_lines += 1
            except Exception:
                pass

    if subtotal_usd == 0.0 and item_lines:
        subtotal_usd = round(total, 2)

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": round(subtotal_usd, 2),
        "freight_usd": round(freight_usd, 2),
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days
    }
