"""Robust transition distillation with structured evidence."""

PROMPT = """{contract}

You are writing one Python function for this contract.

Task requests:
{requests}

Judged runs from this procedure, including successes and failures:
{episodes}

Guidance:
- Match successful behavior as closely as possible.
- Treat failures as negative evidence: if a call, attribute, or action crashes or is rejected, do not rely on it unless the contract explicitly guarantees it.
- Prefer behavior repeated across multiple successful runs over behavior seen once.
- Prefer capabilities named in the contract or clearly demonstrated in successful runs.
- Do not invent hidden APIs, optional methods, or domain-specific shortcuts.
- If an operation might be unavailable, guard it with hasattr/getattr or a similarly safe check, and choose a conservative fallback instead of crashing.
- Keep the function generic to the task described by the contract.
- Return only the function source.
"""

def render_requests(lab):
    parts = []
    for task_id in lab.stream():
        parts.append(f"### Task {task_id}\n{lab.request(task_id)}")
    return "\n\n".join(parts)

def render_episodes(lab):
    parts = []
    for episode in lab.episodes:
        parts.append(f"### Episode {episode.task_id}\n{lab.render(episode)}")
    return "\n\n".join(parts)

async def learn(lab):
    prompt = lab.fill(
        PROMPT,
        contract=lab.contract,
        requests=render_requests(lab),
        episodes=render_episodes(lab),
    )
    return await lab.write(prompt)

