"""Robust transition distillation with contrastive repair: group evidence by task, then revise against practice failures."""

PROMPT = """{contract}

You are writing one Python function for this contract.

Training evidence is grouped by task. Successful runs define the target behavior. Failed runs are counterexamples, but when multiple failures cluster on the same branch, they can identify exactly which branch to change.

Task evidence:
{tasks}

Rules:
- Fit all successful runs first.
- Use failed runs only to eliminate wrong branches or missing special cases.
- If a failure and a success differ by one decision, make that decision explicit.
- Keep the function generic to the contract; do not invent hidden APIs or domain-specific shortcuts.
- Return only the function source.
"""

REPAIRPROMPT = """{contract}

You wrote this function:
{source}

It still fails on these training cases:
{fails}

Revise the function with the smallest change that fixes the failures while preserving the successful behavior.

Rules:
- Keep any correct branches intact.
- Prefer explicit special cases over averaging.
- Return only the revised function source.
"""

def episodeblock(lab, episode):
    status = "SUCCESS" if episode.success else f"FAILURE: {episode.reason}"
    return (
        f"### Episode {episode.task_id} [{status}]\n"
        f"Request:\n{episode.request}\n\n"
        f"{lab.render(episode)}"
    )

def reasonblock(episodes):
    counts = {}
    order = []
    for episode in episodes:
        if episode.success:
            continue
        reason = episode.reason or "unknown failure"
        key = reason[:140]
        if key not in counts:
            counts[key] = 0
            order.append(key)
        counts[key] += 1
    if not order:
        return "None"
    lines = []
    for key in order[:8]:
        lines.append(f"- {counts[key]}x {key}")
    return "\n".join(lines)

def pickedepisodes(episodes):
    successes = [episode for episode in episodes if episode.success]
    failures = [episode for episode in episodes if not episode.success]
    chosen = []
    for episode in successes[:4]:
        chosen.append(episode)
    for episode in failures[:4]:
        chosen.append(episode)
    if not chosen:
        chosen = episodes[:4]
    return chosen

def taskblocks(lab):
    order = list(lab.stream())
    grouped = {}
    for episode in lab.episodes:
        grouped.setdefault(episode.task_id, []).append(episode)
    for task_id in grouped:
        if task_id not in order:
            order.append(task_id)

    parts = []
    for task_id in order:
        episodes = grouped.get(task_id, [])
        if not episodes:
            continue
        chosen = pickedepisodes(episodes)
        parts.append(
            "\n\n".join(
                [
                    f"### Task {task_id} (successes={len([episode for episode in episodes if episode.success])}, failures={len([episode for episode in episodes if not episode.success])})",
                    f"Request:\n{lab.request(task_id)}",
                    "Failure reasons:",
                    reasonblock(episodes),
                    *(episodeblock(lab, episode) for episode in chosen),
                ]
            )
        )
    return "\n\n".join(parts)

def failureblocks(lab, results):
    byid = {}
    for episode in lab.episodes:
        byid[episode.task_id] = episode
    parts = []
    for task_id, reward, reason, observations in results:
        if reward:
            continue
        episode = byid.get(task_id)
        if episode is None:
            continue
        parts.append(
            "\n\n".join(
                [
                    f"### Task {task_id} (failed practice)",
                    f"Request:\n{lab.request(task_id)}",
                    f"Practice reason:\n{reason}",
                    f"Practice observations:\n{observations}",
                    episodeblock(lab, episode),
                ]
            )
        )
    return "\n\n".join(parts)

async def score(lab, source):
    results = []
    total = 0
    for task_id in lab.stream():
        reward, reason, observations = await lab.practice(source, task_id)
        results.append((task_id, reward, reason, observations))
        try:
            total += reward
        except TypeError:
            if reward:
                total += 1
    return total, results

async def learn(lab):
    prompt = lab.fill(PROMPT, contract=lab.contract, tasks=taskblocks(lab))
    source = await lab.write(prompt)

    best = source
    bestscore, results = await score(lab, source)

    if bestscore < len(list(lab.stream())):
        fails = failureblocks(lab, results)
        if fails:
            repair = lab.fill(REPAIRPROMPT, contract=lab.contract, source=source, fails=fails)
            revised = await lab.write(repair)
            revisedscore, revisedresults = await score(lab, revised)
            if revisedscore >= bestscore:
                best = revised
                bestscore = revisedscore
                results = revisedresults

    return best

