def reimbursable_total(api, trip_id: str) -> dict:
    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    city = trip["city"]
    start = trip["start"]
    month = start[:7]
    allowances = policy["allowances_usd"][city]
    rates = policy["company_rates_usd_per_unit"][month]

    def is_alcohol(note):
        return "alcohol" in note.lower()

    def to_usd(amount, currency):
        if currency == "USD":
            return float(amount)
        return float(amount) * float(rates[currency])

    receipts = trip["receipts"]
    meal_by_day = {}
    total = 0.0

    for r in receipts:
        note = r.get("note", "")
        if note is None:
            note = ""
        if is_alcohol(note):
            continue

        category = r["category"]
        amount = float(r["amount"])
        currency = r["currency"]
        usd = to_usd(amount, currency)

        if category == "meal":
            day = r["date"]
            meal_by_day[day] = meal_by_day.get(day, 0.0) + usd

        elif category == "hotel":
            total += min(usd, float(allowances["hotel_per_night"]))

        elif category == "taxi":
            if usd > 40.0 and len(note.strip()) == 0:
                continue
            total += usd

    meal_limit = float(allowances["meals_per_day"])
    for day_total in meal_by_day.values():
        total += min(day_total, meal_limit)

    return {"total_usd": round(total + 1e-9, 2)}
