    requested_n = days_from_civil(yr, mr, dr)
    days_since_delivery = requested_n - delivered_n

    window = int(p.get("return_window_days", {}).get(category, 0))
    member_extra = int(p.get("member_extra_days", 0))
    tier = ""
    if isinstance(customer, dict):
        tier = str(customer.get("tier", ""))
    if tier == "plus":
        window += member_extra

    holiday = False
    if (md == 11 and dd >= 15) or (md == 12) or (md == 1 and dd <= 31):
        if md == 11 and dd < 15:
            holiday = False
        else:
            holiday = True

    damaged = False
    reason = str(r.get("reason", "")).lower()
    if "damaged" in reason:
        damaged = True

    amount = 0.0
    method = "card"

    if damaged and days_since_delivery <= int(p.get("damaged_refund_days", 90)):
        amount = round(price + shipping, 2)
        issue = getattr(api, "issue_refund", None)
        if issue is not None:
            return issue({"return_id": return_id, "amount_usd": amount, "method": "card"})
        return {"method": "card", "amount_usd": amount}

    if final_sale:
        decline = getattr(api, "decline_return", None)
        if decline is not None:
            return decline(return_id)
        return {"method": "decline", "amount_usd": 0}

    if category == "beauty" and opened:
        decline = getattr(api, "decline_return", None)
        if decline is not None:
            return decline(return_id)
        return {"method": "decline", "amount_usd": 0}

    if holiday:
        method = "card"
    else:
        if days_since_delivery <= window:
            method = "card"
        elif days_since_delivery <= window + int(p.get("store_credit_days_after_window", 30)):
            method = "store_credit"
        else:
            decline = getattr(api, "decline_return", None)
            if decline is not None:
                return decline(return_id)
            return {"method": "decline", "amount_usd": 0}

    amount = price

    if opened and category == "electronics" and not holiday:
        amount = amount - (price * float(p.get("restocking_fee_opened_electronics", 0)))
    if holiday:
        amount = price

    acc_vals = {}
    for acc in item.get("accessories", []):
        acc_vals[str(acc.get("name", ""))] = float(acc.get("value", 0))
    missing_total = 0.0
    for name in missing:
        missing_total += float(acc_vals.get(str(name), 0))
    amount -= missing_total

    if amount < 0:
        amount = 0.0

    amount = round(amount, 2)
    if method == "store_credit" and holiday:
        method = "card"

    issue = getattr(api, "issue_refund", None)
    if issue is not None:
        return issue({"return_id": return_id, "amount_usd": amount, "method": method})
    return {"method": method, "amount_usd": amount}
