def parse_invoice(api, doc_id: str) -> dict:
    text = api.read_document(doc_id)["text"]

    def first_line_with(prefixes):
        lines = text.splitlines()
        for line in lines:
            s = line.strip()
            for p in prefixes:
                if s.startswith(p):
                    return s
        return ""

    def after_markers(line, markers):
        s = line.strip()
        for m in markers:
            if m in s:
                return s.split(m, 1)[1].strip()
        return ""

    def parse_date(s):
        s = s.strip()
        if "," in s:
            parts = s.replace("|", " ").split()
            for i, w in enumerate(parts):
                if w.lower().startswith("dated") and i + 1 < len(parts):
                    tail = " ".join(parts[i + 1:])
                    return parse_date(tail)
            s = s.replace("Dated", "").replace("dated", "").strip(" ,.")
        if "/" in s:
            parts = s.split("/")
            if len(parts) == 3:
                a = parts[0].strip()
                b = parts[1].strip()
                c = parts[2].strip()
                if len(a) == 4:
                    return a + "-" + b.zfill(2) + "-" + c.zfill(2)
                return c + "-" + a.zfill(2) + "-" + b.zfill(2)
        month_map = {
            "january": "01", "february": "02", "march": "03", "april": "04",
            "may": "05", "june": "06", "july": "07", "august": "08",
            "september": "09", "october": "10", "november": "11", "december": "12"
        }
        parts = s.replace(",", "").split()
        if len(parts) >= 3:
            if parts[0].isdigit():
                d = parts[0].zfill(2)
                m = month_map.get(parts[1].lower(), "01")
                y = parts[2]
                return y + "-" + m + "-" + d
            m = month_map.get(parts[0].lower(), "01")
            d = parts[1].zfill(2)
            y = parts[2]
            return y + "-" + m + "-" + d
        return s

    def parse_money(s):
        s = s.strip().replace("$", "").replace(",", "")
        return round(float(s), 2)

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal = 0.0
    freight = 0.0
    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    lines = text.splitlines()

    for line in lines:
        s = line.strip()

        if not invoice_number:
            if "Invoice No:" in s:
                invoice_number = after_markers(s, ["Invoice No:"])
            elif s.startswith("INVOICE "):
                invoice_number = s.split(" ", 1)[1].strip()
            elif s.startswith("INVOICE;"):
                parts = s.split(";")
                if len(parts) >= 3:
                    invoice_number = parts[2].strip()

        if not po_number:
            if "PO Number:" in s:
                po_number = after_markers(s, ["PO Number:"])
            elif "Customer PO" in s:
                po_number = after_markers(s, ["Customer PO"])
            elif "ORDER REF;" in s:
                parts = s.split(";")
                if len(parts) >= 3:
                    po_number = parts[2].strip()

        if not invoice_date:
            if "Invoice Date:" in s:
                invoice_date = parse_date(after_markers(s, ["Invoice Date:"]))
            elif s.startswith("Dated "):
                invoice_date = parse_date(s[len("Dated "):])
            elif s.startswith("DATE;"):
                parts = s.split(";")
                if len(parts) >= 2:
                    invoice_date = parse_date(parts[1].strip())
            elif "dated" in s.lower() and "invoice" in s.lower():
                idx = s.lower().find("dated")
                invoice_date = parse_date(s[idx + 5:].strip(" ."))

        low = s.lower()
        if "terms:" in low or low.startswith("terms;"):
            term_text = after_markers(s, ["Terms:", "TERMS;"])
            term_low = term_text.lower().replace(" ", "")
            if "/" in term_low and "net" in term_low:
                a = term_low.split("/")[0]
                b = term_low.split("/")[1]
                c = term_low.split("net")[-1]
                try:
                    discount_percent = float(a)
                except Exception:
                    discount_percent = 0.0
                try:
                    discount_days = int(b)
                except Exception:
                    discount_days = 0
                try:
                    net_days = int(c)
                except Exception:
                    net_days = 0
            elif "n30" in term_low:
                discount_percent = 1
                discount_days = 10
                net_days = 30

        if "net 45" in low:
            net_days = 45
        elif "net 30" in low:
            net_days = 30
        elif "n30" in low:
            net_days = 30

        if "1.5% off" in low:
            discount_percent = 1.5
            discount_days = 15
        elif "2/10" in low:
            discount_percent = 2
            discount_days = 10
        elif "1/10" in low:
            discount_percent = 1
            discount_days = 10

        if "subtotal:" in low or "goods total" in low:
            if "subtotal:" in low:
                subtotal = parse_money(after_markers(s, ["Subtotal:"]))
            else:
                idx = low.find("goods total")
                tail = s[idx + len("Goods total"):].strip()
                subtotal = parse_money(tail.split("|", 1)[0])

        if "freight:" in low or "delivery charge" in low or "shipping;" in low or "carriage comes to" in low:
            if "freight:" in low:
                freight = parse_money(after_markers(s, ["Freight:"]))
            elif "delivery charge" in low:
                tail = s.split("Delivery charge", 1)[1].strip()
                freight = parse_money(tail.split("|", 1)[0])
            elif "shipping;" in low:
                parts = s.split(";")
                freight = parse_money(parts[-1])
            elif "carriage comes to" in low:
                tail = s.split("Carriage comes to", 1)[1].strip()
                freight = parse_money(tail.split(".", 1)[0])

        if "shipping" == low or low.startswith("shipping;"):
            parts = s.split(";")
            if len(parts) >= 2:
                freight = parse_money(parts[1])

    if not invoice_number:
        for line in lines:
            s = line.strip()
            if s.startswith("INVOICE ") and len(s.split()) >= 2:
                invoice_number = s.split(" ", 1)[1].strip()
                break

    if not po_number:
        for line in lines:
            s = line.strip()
            if "PO-" in s:
                idx = s.find("PO-")
                po_number = s[idx:].split()[0].strip(".,;")
                break

    if not invoice_date:
        for line in lines:
            s = line.strip()
            if "DATE;" in s:
                parts = s.split(";")
                if len(parts) >= 2:
                    invoice_date = parse_date(parts[1].strip())
                    break

    if invoice_date and len(invoice_date) != 10 and "/" not in invoice_date:
        invoice_date = parse_date(invoice_date)

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": round(subtotal, 2),
        "freight_usd": round(freight, 2),
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }
