def refund_decision(api, return_id: str) -> dict:
    ret = api.read_return(return_id)
    if not isinstance(ret, dict):
        return {"method": "decline", "amount_usd": 0.0}

    order_id = ret.get("order_id")
    order = api.read_order(order_id) if order_id is not None else {}
    if not isinstance(order, dict):
        order = {}

    customer = None
    customer_id = order.get("customer_id")
    if customer_id is not None:
        try:
            customer = api.read_customer(customer_id)
        except Exception:
            customer = None
    if not isinstance(customer, dict):
        customer = {}

    policy = api.read_policy()
    if not isinstance(policy, dict):
        policy = {}

    items = order.get("items")
    if not isinstance(items, list):
        items = []

    sku = ret.get("sku")
    item = {}
    for it in items:
        if isinstance(it, dict) and it.get("sku") == sku:
            item = it
            break

    category = item.get("category")
    price = float(item.get("price") or 0.0)
    shipping = float(item.get("shipping") or 0.0)
    final_sale = bool(item.get("final_sale"))

    opened = bool(ret.get("opened"))
    missing_accessories = ret.get("missing_accessories")
    if not isinstance(missing_accessories, list):
        missing_accessories = []

    accessories = item.get("accessories")
    if not isinstance(accessories, list):
        accessories = []

    return_windows = policy.get("return_window_days")
    if not isinstance(return_windows, dict):
        return_windows = {}

    delivered_on = str(order.get("delivered_on") or "")
    requested_on = str(ret.get("requested_on") or "")

    def _ymd(s):
        parts = s.split("-")
        if len(parts) != 3:
            return (0, 0, 0)
        try:
            return (int(parts[0]), int(parts[1]), int(parts[2]))
        except Exception:
            return (0, 0, 0)

    def _days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12):
            return 31
        if m in (4, 6, 9, 11):
            return 30
        leap = (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))
        return 29 if leap else 28

    def _days_from_ymd(y, m, d):
        days = 0
        for yy in range(1, y):
            leap = (yy % 4 == 0 and (yy % 100 != 0 or yy % 400 == 0))
            days += 366 if leap else 365
        for mm in range(1, m):
            days += _days_in_month(y, mm)
        days += d
        return days

    dy, dm, dd = _ymd(delivered_on)
    ry, rm, rd = _ymd(requested_on)
    delivered_days = _days_from_ymd(dy, dm, dd)
    requested_days = _days_from_ymd(ry, rm, rd)
    days_after_delivery = requested_days - delivered_days

    holiday_delivery = (dm == 11 and dd >= 15) or (dm == 12)
    holiday_refund_deadline = (ry < 2027) or (ry == 2027 and (rm < 1 or (rm == 1 and rd <= 31)))
    holiday_applies = holiday_delivery and holiday_refund_deadline

    tier = str(customer.get("tier") or "")
    extra_days = int(policy.get("member_extra_days") or 0) if tier == "plus" else 0
    window_days = int(return_windows.get(category) or 0) + extra_days

    damaged = str(ret.get("reason") or "").lower() == "damaged" or str(ret.get("reason") or "").lower() == "arrived damaged"
    damaged_days = int(policy.get("damaged_refund_days") or 0)

    if final_sale:
        return {"method": "decline", "amount_usd": 0.0}
    if category == "beauty" and opened:
        return {"method": "decline", "amount_usd": 0.0}

    method = "card"
    if not holiday_applies:
        if days_after_delivery > window_days:
            if days_after_delivery <= window_days + int(policy.get("store_credit_days_after_window") or 0):
                method = "store_credit"
            else:
                return {"method": "decline", "amount_usd": 0.0}

    amount = price
    if damaged and days_after_delivery <= damaged_days:
        amount = price + shipping
        method = "card"
    else:
        if opened and category == "electronics" and not holiday_applies:
            amount = amount * (1.0 - float(policy.get("restocking_fee_opened_electronics") or 0.0))
        missing_value = 0.0
        missing_set = set()
        for ma in missing_accessories:
            missing_set.add(str(ma))
        for acc in accessories:
            if isinstance(acc, dict) and str(acc.get("name") or "") in missing_set:
                missing_value += float(acc.get("value") or 0.0)
        amount = amount - missing_value

    if amount < 0:
        amount = 0.0

    amount = round(amount + 1e-12, 2)
    if amount == 0:
        return {"method": "decline", "amount_usd": 0.0}
    return {"method": method, "amount_usd": amount}
