def refund_decision(api, return_id: str) -> dict:
    r = api.read_return(return_id)
    order = api.read_order(r["order_id"])
    policy = api.read_policy()

    def ymd(s):
        if not isinstance(s, str):
            return (0, 0, 0)
        parts = s.split("-")
        if len(parts) != 3:
            return (0, 0, 0)
        try:
            return (int(parts[0]), int(parts[1]), int(parts[2]))
        except Exception:
            return (0, 0, 0)

    def date_to_ordinal(s):
        y, m, d = ymd(s)
        leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
        month_days = [31, 28 + (1 if leap else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        n = d
        i = 0
        while i < m - 1:
            n += month_days[i]
            i += 1
        return y * 365 + (y // 4) - (y // 100) + (y // 400) + n

    def days_between(a, b):
        return date_to_ordinal(b) - date_to_ordinal(a)

    def item_for_sku(items, sku):
        for item in items:
            if item.get("sku") == sku:
                return item
        return {}

    def find_accessory_value(accessories, name):
        for acc in accessories:
            if acc.get("name") == name:
                return float(acc.get("value", 0))
        return 0.0

    def get_customer(obj):
        if isinstance(obj, dict):
            cid = obj.get("customer_id")
            if cid:
                return api.read_customer(cid)
        return {}

    item = item_for_sku(order.get("items", []), r.get("sku"))
    category = item.get("category")
    price = float(item.get("price", 0))
    shipping = float(item.get("shipping", 0))
    final_sale = bool(item.get("final_sale", False))
    opened = bool(r.get("opened", False))
    missing = r.get("missing_accessories", [])
    delivered_on = order.get("delivered_on")
    requested_on = r.get("requested_on")

    cust = get_customer(order)
    tier = ""
    if isinstance(cust, dict):
        tier = cust.get("tier", "") or ""

    windows = policy.get("return_window_days", {})
    window = int(windows.get(category, 0))
    extra = int(policy.get("member_extra_days", 0)) if tier == "plus" else 0
    allowed_window = window + extra

    is_holiday = False
    y, m, d = ymd(delivered_on)
    if m == 11 and d >= 15:
        is_holiday = True
    if m == 12:
        is_holiday = True

    days = days_between(delivered_on, requested_on)
    if is_holiday and ymd(requested_on)[1] == 1 and ymd(requested_on)[2] <= 31:
        days = 0

    if final_sale:
        return {"method": "decline", "amount_usd": 0.0}

    if category == "beauty" and opened:
        return {"method": "decline", "amount_usd": 0.0}

    if days < 0:
        return {"method": "decline", "amount_usd": 0.0}

    if days > allowed_window + int(policy.get("store_credit_days_after_window", 0)):
        return {"method": "decline", "amount_usd": 0.0}

    amount = price
    method = "card" if days <= allowed_window else "store_credit"

    if method == "card" and category == "electronics" and opened:
        if not is_holiday:
            amount = amount * (1.0 - float(policy.get("restocking_fee_opened_electronics", 0)))
    if method == "card" and is_holiday:
        pass

    missing_total = 0.0
    accessories = item.get("accessories", [])
    for name in missing:
        missing_total += find_accessory_value(accessories, name)

    amount -= missing_total
    if amount < 0:
        amount = 0.0

    if category == "electronics" and opened and not is_holiday:
        amount = amount
    if method == "card" and is_holiday:
        amount = price
    if method == "card" and days <= allowed_window and is_holiday and category == "electronics" and opened:
        amount = price

    amount = round(amount + 1e-9, 2)

    if amount <= 0:
        return {"method": "decline", "amount_usd": 0.0}
    return {"method": method, "amount_usd": amount}
