"""Transition distillation with contrastive failure emphasis.

Learn from every judged run, but surface the rejection reasons and any
contrastive clauses first so the writer can correct missing conditions instead
of copying the majority behavior.
"""

PROMPT = """{contract}

Contrastive summary of the judged runs:
{summary}

Rejected runs are listed first, then accepted runs:
{episodes}

Write the function by distilling the successful behavior, but do not ignore
the failures. In particular:

- treat each rejection reason as a concrete counterexample;
- if a reason contains a contrastive clause such as "but", "however", or
  "yet", treat the clause after that pivot as a likely missing rule;
- when successes and failures differ only by a condition, preserve that
  condition explicitly;
- be conservative about external APIs: use only objects, attributes, and
  methods that are explicitly present in the contract or demonstrably used in
  the runs, and probe optional capabilities before calling them.

{episodes}"""


def contrast_clause(reason):
    text = "" if reason is None else str(reason)
    lowered = text.lower()
    for marker in (" but ", " however ", " yet ", " instead ", " rather than "):
        position = lowered.find(marker)
        if position != -1:
            clause = text[position + len(marker):].strip(" .;:")
            if clause:
                return clause
    return text.strip() or "(no reason provided)"


def summarize_episodes(episodes):
    task_counts = {}
    failure_reasons = {}
    contrast_clues = {}
    mixed_tasks = []

    for episode in episodes:
        task_id = getattr(episode, "task_id", "?")
        success = bool(getattr(episode, "success", False))

        stats = task_counts.get(task_id)
        if stats is None:
            stats = [0, 0]
            task_counts[task_id] = stats
        stats[0] += 1
        if success:
            stats[1] += 1
        else:
            reason = getattr(episode, "reason", "") or "(no reason provided)"
            failure_reasons[reason] = failure_reasons.get(reason, 0) + 1
            clue = contrast_clause(reason)
            contrast_clues[clue] = contrast_clues.get(clue, 0) + 1

    for task_id, stats in task_counts.items():
        if 0 < stats[1] < stats[0]:
            mixed_tasks.append((task_id, stats[1], stats[0]))

    lines = []

    if task_counts:
        lines.append("Task acceptance summary:")
        for task_id, stats in sorted(task_counts.items(), key=lambda item: str(item[0])):
            lines.append(f"- {task_id}: {stats[1]}/{stats[0]} accepted")

    if mixed_tasks:
        lines.append("Tasks with both accepted and rejected runs:")
        for task_id, accepted, total in sorted(mixed_tasks, key=lambda item: str(item[0])):
            lines.append(f"- {task_id}: {accepted}/{total} accepted")

    if failure_reasons:
        lines.append("Most common rejection reasons:")
        for reason, count in sorted(failure_reasons.items(), key=lambda item: (-item[1], str(item[0]))):
            lines.append(f"- {count}x {reason}")

    if contrast_clues:
        lines.append("Likely missing adjustments extracted from rejection reasons:")
        for clue, count in sorted(contrast_clues.items(), key=lambda item: (-item[1], str(item[0]))):
            lines.append(f"- {count}x {clue}")

    lines.append(
        "Guidance: do not let a broad successful pattern erase a specific correction "
        "named by a failure; if a rejection points to a missing subtraction, filter, "
        "threshold, or condition, encode it explicitly."
    )

    return "\n".join(lines)


async def learn(lab):
    summary = summarize_episodes(lab.episodes)

    rejected = []
    accepted = []
    for episode in lab.episodes:
        rendered = lab.render(episode)
        if getattr(episode, "success", False):
            accepted.append(rendered)
        else:
            rejected.append(rendered)

    episodes = "\n\n".join(rejected + accepted)
    prompt = lab.fill(PROMPT, contract=lab.contract, summary=summary, episodes=episodes)
    return await lab.write(prompt)

