def parse_invoice(api, doc_id: str) -> dict:
    text = ""
    if hasattr(api, "read_document") and callable(getattr(api, "read_document")):
        doc = api.read_document(doc_id)
        if isinstance(doc, dict):
            text = doc.get("text", "")
        else:
            text = str(doc)

    def find_first(lines, keys):
        for line in lines:
            low = line.lower()
            for key in keys:
                if key in low:
                    return line
        return ""

    def after_marker(line, markers):
        for marker in markers:
            idx = line.lower().find(marker.lower())
            if idx != -1:
                return line[idx + len(marker):].strip(" :;|,\t")
        return ""

    def digits_only(s):
        out = ""
        for ch in s:
            if ch.isdigit():
                out += ch
        return out

    def parse_date(s):
        s = s.strip()
        if not s:
            return ""
        s = s.replace(",", "")
        months = {
            "january": "01", "february": "02", "march": "03", "april": "04",
            "may": "05", "june": "06", "july": "07", "august": "08",
            "september": "09", "october": "10", "november": "11", "december": "12"
        }
        parts = s.replace("|", " ").replace("/", "-").split()
        if len(parts) >= 3 and parts[0].isdigit() and len(parts[0]) == 4:
            return parts[0] + "-" + parts[1].zfill(2) + "-" + parts[2].zfill(2)
        if len(parts) >= 3 and parts[0].isdigit() and parts[1].isdigit() and len(parts[2]) == 4:
            return parts[2] + "-" + parts[0].zfill(2) + "-" + parts[1].zfill(2)
        if len(parts) >= 3:
            for i in range(len(parts) - 2):
                a, b, c = parts[i], parts[i + 1], parts[i + 2]
                if a.isdigit() and c.isdigit() and len(c) == 4:
                    m = months.get(b.lower(), "")
                    if m:
                        return c + "-" + m + "-" + a.zfill(2)
        return ""

    def parse_money(s):
        s = s.replace(",", "").strip()
        if "$" in s:
            s = s.replace("$", "")
        n = ""
        seen = False
        for ch in s:
            if ch.isdigit() or ch == "." or (ch == "-" and not seen):
                n += ch
                seen = True
        try:
            return float(n)
        except Exception:
            return 0.0

