                if len(nums) >= 1 and "/" in left:
                    a, b = left.split("/", 1)[0], left.split("/", 1)[1].split()[0]
                    if a.strip().isdigit() and b.strip().isdigit():
                        discount_days = int(a.strip())
                        discount_percent = float(a.strip())
            if "1.5%" in low:
