            elif "net 30" in low or "n30" in low:
                net_days = 30
            elif "net 60" in low:
                net_days = 60
            if "10" in low and discount_days == 0 and ("/10" in low or "1/10" in low or "2/10" in low):
                discount_days = 10
            if "15" in low and "1.5" in low:
                discount_days = 15
        if "payment terms net 45" in low:
            net_days = 45
        if "net 30" in low and not net_days:
            net_days = 30
        if "net 45" in low:
