    if not invoice_number:
        for line in lines:
            if "invoice" in line.lower():
                parts = line.replace(";", " ").split()
                for p in parts:
                    if any(ch.isdigit() for ch in p) and p.lower() != "invoice":
                        invoice_number = p.strip(".,;:")
                        break
                if invoice_number:
