                break

    for line in lines:
        low = line.lower()
        if "subtotal" in low or "goods total" in low:
            vals = []
            for part in line.replace("|", " ").replace(":", " ").split():
                if any(ch.isdigit() for ch in part):
                    vals.append(part)
            if vals:
                subtotal = parse_money(vals[-1])
        if "freight" in low or "delivery charge" in low or "carriage" in low or "shipping" in low:
            vals = []
            for part in line.replace("|", " ").replace(":", " ").split():
                if any(ch.isdigit() for ch in part):
