                nums = []
                for p in parts:
                    if p.replace(".", "", 1).replace(",", "").replace("$", "").replace("-", "").isdigit() or ("." in p and any(ch.isdigit() for ch in p)):
                        nums.append(p)
                if len(nums) >= 2 and (" x " in (" " + line.lower() + " ") or ";" in line):
                    try:
