def amount_payable(api, invoice_id: str) -> dict:
    def get(d, key, default=None):
        try:
            return d[key]
        except Exception:
            return default

    def read_one(method_name, **kwargs):
        meth = getattr(api, method_name, None)
        if not callable(meth):
            return {}
        try:
            return meth(kwargs)
        except Exception:
            return {}

    def ymd_add_days(ymd, days):
        y = int(ymd[0:4])
        m = int(ymd[5:7])
        d = int(ymd[8:10])

        def leap(yy):
            return (yy % 4 == 0 and yy % 100 != 0) or (yy % 400 == 0)

        month_days = [31, 28 + (1 if leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        d += int(days)
        while d > month_days[m - 1]:
            d -= month_days[m - 1]
            m += 1
            if m > 12:
                m = 1
                y += 1
                month_days = [31, 28 + (1 if leap(y) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)

    inv = read_one("read_invoice", invoice_id=invoice_id)
    if not inv:
        return {}

    po_number = get(inv, "po_number", "")
    client_id = get(inv, "client_id", "")
    invoice_date = get(inv, "invoice_date", "")
    terms = get(inv, "terms", {}) or {}
    lines = get(inv, "lines", []) or []
    freight = float(get(inv, "freight_usd", 0.0) or 0.0)

    po = read_one("read_purchase_order", po_number=po_number)
    if get(po, "error") is not None:
        po = {}

    client = read_one("read_client_terms", client_id=client_id)
    if get(client, "error") is not None:
        client = {}

    taxed_categories = set(get(client, "taxed_categories", []) or [])
    tax_rate = float(get(client, "sales_tax_rate", 0.0) or 0.0)

    delivered_by_sku = {}
    po_lines = get(po, "lines", []) or []
    for pl in po_lines:
        sku = get(pl, "sku", "")
        delivered = int(get(pl, "delivered", 0) or 0)
        ordered = int(get(pl, "ordered", 0) or 0)
        delivered_by_sku[sku] = min(delivered, ordered)

    goods = 0.0
    taxable_goods = 0.0
    for line in lines:
        sku = get(line, "sku", "")
        qty = int(get(line, "quantity", 0) or 0)
        delivered = delivered_by_sku.get(sku, qty)
        if delivered > qty:
            delivered = qty
        unit_price = float(get(line, "unit_price", 0.0) or 0.0)
        category = get(line, "category", "")
        line_total = delivered * unit_price
        goods += line_total
        if category in taxed_categories:
            taxable_goods += line_total

    discount_percent = float(get(terms, "discount_percent", 0.0) or 0.0)
    discount_days = int(get(terms, "discount_days", 0) or 0)
    net_days = int(get(terms, "net_days", 0) or 0)

    if discount_percent > 0 and discount_days > 0:
        pay_on = ymd_add_days(invoice_date, discount_days)
        multiplier = 1.0 - (discount_percent / 100.0)
        amount = (goods * multiplier) + (taxable_goods * tax_rate) + freight
    else:
        pay_on = ymd_add_days(invoice_date, net_days)
        amount = goods + (taxable_goods * tax_rate) + freight

    round_down_whole = False
    rules = get(client, "rules", []) or []
    for rule in rules:
        r = str(rule).lower()
        if "rounding down" in r or "whole dollars" in r:
            round_down_whole = True
            break

    if round_down_whole:
        amount = float(int(amount))

    amount = round(amount + 1e-12, 2)

    schedule = getattr(api, "schedule_payment", None)
    if callable(schedule):
        try:
            return schedule({"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on})
        except Exception:
            pass

    return {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}
