        try:
            if isinstance(obj, dict):
                return obj.get(key, default)
        except Exception:
            pass
        return default

    city = get_value(trip, "city", "")
    start = get_value(trip, "start", "")
    receipts = get_value(trip, "receipts", [])
    allowances = get_value(policy, "allowances_usd", {})
    rates_by_month = get_value(policy, "company_rates_usd_per_unit", {})

    month = ""
    try:
        month = start[:7] if isinstance(start, str) and len(start) >= 7 else ""
    except Exception:
        month = ""

    city_allow = get_value(allowances, city, {})
    rate_map = get_value(rates_by_month, month, {})

    def to_usd(amount, currency):
        try:
            if not isinstance(amount, (int, float)):
                amount = float(amount)
        except Exception:
            return 0.0
        try:
            if currency == "USD":
                return float(amount)
            rate = get_value(rate_map, currency, None)
            if rate is None:
                return 0.0
            return float(amount) * float(rate)
        except Exception:
            return 0.0

    meal_by_day = {}
    total = 0.0

    try:
        for r in receipts if isinstance(receipts, list) else []:
            category = get_value(r, "category", "")
            note = get_value(r, "note", "")
            date = get_value(r, "date", "")
            amount = get_value(r, "amount", 0.0)
            currency = get_value(r, "currency", "")

            note_text = note if isinstance(note, str) else str(note)
            if "alcohol" in note_text.lower():
