            usd = to_usd(amount, currency)
            if usd <= 0:
                continue

            if category == "meal":
                meal_by_day[date] = meal_by_day.get(date, 0.0) + usd
            elif category == "hotel":
                limit = get_value(city_allow, "hotel_per_night", 0.0)
                try:
                    total += min(float(usd), float(limit))
                except Exception:
                    total += float(usd)
            elif category == "taxi":
                if usd > 40.0:
                    if isinstance(note_text, str) and len(note_text.strip()) == 0:
                        continue
                total += usd
            else:
                total += usd

        meal_limit = get_value(city_allow, "meals_per_day", 0.0)
        for _, spent in meal_by_day.items():
            try:
                total += min(float(spent), float(meal_limit))
            except Exception:
                total += float(spent)

    except Exception:
        return {"total_usd": round(total, 2)}

    return {"total_usd": round(total, 2)}
