def refund_decision(api, return_id: str) -> dict:
    def _safe_call(func, *args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception:
            return None

    def _get(d, key, default=None):
        if isinstance(d, dict):
            return d.get(key, default)
        return default

    def _to_date_tuple(s):
        try:
            parts = str(s).split("-")
            if len(parts) != 3:
                return None
            return int(parts[0]), int(parts[1]), int(parts[2])
        except Exception:
            return None

    def _date_to_ordinal(y, m, d):
        mdays = [31, 28 + (1 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        days = d
        i = 0
        while i < m - 1:
            days += mdays[i]
            i += 1
        y1 = y - 1
        days += 365 * y1 + y1 // 4 - y1 // 100 + y1 // 400
        return days

    def _days_between(a, b):
        ta = _to_date_tuple(a)
        tb = _to_date_tuple(b)
        if ta is None or tb is None:
            return None
        return _date_to_ordinal(tb[0], tb[1], tb[2]) - _date_to_ordinal(ta[0], ta[1], ta[2])

    ret = _safe_call(api.read_return, return_id)
    if not isinstance(ret, dict):
        return {"method": "decline", "amount_usd": 0}

    order_id = _get(ret, "order_id")
    sku = _get(ret, "sku")
    requested_on = _get(ret, "requested_on")
    reason = str(_get(ret, "reason", "")).lower()
    opened = bool(_get(ret, "opened", False))
    missing_accessories = _get(ret, "missing_accessories", [])
    if not isinstance(missing_accessories, list):
        missing_accessories = []

    order = _safe_call(api.read_order, order_id)
    if not isinstance(order, dict):
        return {"method": "decline", "amount_usd": 0}

    policy = _safe_call(api.read_policy)
    if not isinstance(policy, dict):
        return {"method": "decline", "amount_usd": 0}

    item = None
    items = _get(order, "items", [])
    if isinstance(items, list):
        for it in items:
            if isinstance(it, dict) and _get(it, "sku") == sku:
                item = it
                break
    if not isinstance(item, dict):
        return {"method": "decline", "amount_usd": 0}

    category = str(_get(item, "category", "")).lower()
    price = float(_get(item, "price", 0) or 0)
    shipping = float(_get(item, "shipping", 0) or 0)
    final_sale = bool(_get(item, "final_sale", False))
    accessories = _get(item, "accessories", [])
    if not isinstance(accessories, list):
        accessories = []

    if final_sale:
        return {"method": "decline", "amount_usd": 0}

    delivered_on = _get(order, "delivered_on")
    if not delivered_on:
        return {"method": "decline", "amount_usd": 0}

    window_days = _get(policy, "return_window_days", {})
    base_window = 0
    if isinstance(window_days, dict):
        try:
            base_window = int(window_days.get(category, 0) or 0)
        except Exception:
            base_window = 0

    customer = _safe_call(api.read_customer, _get(order, "customer_id"))
    tier = ""
    if isinstance(customer, dict):
        tier = str(_get(customer, "tier", "")).lower()

    if tier == "plus":
        base_window += int(_get(policy, "member_extra_days", 0) or 0)

    days_since_delivery = _days_between(delivered_on, requested_on)
    if days_since_delivery is None:
        return {"method": "decline", "amount_usd": 0}

    holiday = False
    dt = _to_date_tuple(delivered_on)
    if dt is not None:
        m, d = dt[1], dt[2]
        if (m == 11 and d >= 15) or (m == 12) or (m == 1 and d <= 31):
            if (m == 11 and d >= 15) or (m == 12) or (m == 1 and d <= 31):
                holiday = True

    if holiday and days_since_delivery >= 0 and days_since_delivery <= 53:
        amount = price
        if opened and category == "electronics":
            amount -= price * float(_get(policy, "restocking_fee_opened_electronics", 0) or 0)
        missing = 0.0
        acc_map = {}
        if isinstance(accessories, list):
            for a in accessories:
                if isinstance(a, dict):
                    acc_map[str(_get(a, "name", ""))] = float(_get(a, "value", 0) or 0)
        for name in missing_accessories:
            missing += float(acc_map.get(str(name), 0) or 0)
        amount -= missing
        if amount < 0:
            amount = 0.0
        return {"method": "card", "amount_usd": round(amount, 2)}

    if category == "beauty" and opened:
        return {"method": "decline", "amount_usd": 0}

    if category == "electronics" and opened:
        amount = price * (1 - float(_get(policy, "restocking_fee_opened_electronics", 0) or 0))
    else:
        amount = price

    acc_map = {}
    if isinstance(accessories, list):
        for a in accessories:
            if isinstance(a, dict):
                acc_map[str(_get(a, "name", ""))] = float(_get(a, "value", 0) or 0)

    missing_total = 0.0
    for name in missing_accessories:
        missing_total += float(acc_map.get(str(name), 0) or 0)
    amount -= missing_total

    if amount < 0:
        amount = 0.0

    if days_since_delivery <= base_window:
        return {"method": "card", "amount_usd": round(amount, 2)}

    credit_days = int(_get(policy, "store_credit_days_after_window", 0) or 0)
    if days_since_delivery <= base_window + credit_days:
        return {"method": "store_credit", "amount_usd": round(amount, 2)}

    if days_since_delivery <= int(_get(policy, "damaged_refund_days", 0) or 0):
        if "damag" in reason:
            return {"method": "card", "amount_usd": round(price + shipping, 2)}

    return {"method": "decline", "amount_usd": 0}
