def refund_decision(api, return_id: str) -> dict:
    def call(name, *args, **kwargs):
        try:
            fn = getattr(api, name)
        except Exception:
            return None
        try:
            return fn(*args, **kwargs)
        except Exception:
            return None

    def as_dict(x):
        return x if isinstance(x, dict) else {}

    def get(d, key, default=None):
        try:
            return d[key]
        except Exception:
            return default

    def to_int_day(s):
        try:
            parts = str(s).split("-")
            if len(parts) == 3:
                return int(parts[0]) * 372 + int(parts[1]) * 31 + int(parts[2])
        except Exception:
            pass
        return None

    r = as_dict(call("read_return", return_id))
    order_id = get(r, "order_id")
    sku = get(r, "sku")
    reason = str(get(r, "reason", "")).lower()
    opened = bool(get(r, "opened", False))
    missing = get(r, "missing_accessories", [])
    if not isinstance(missing, list):
        missing = []

    o = as_dict(call("read_order", order_id))
    items = get(o, "items", [])
    if not isinstance(items, list):
        items = []

    target = {}
    for item in items:
        if isinstance(item, dict) and get(item, "sku") == sku:
            target = item
            break

    policy = as_dict(call("read_policy"))
    windows = as_dict(get(policy, "return_window_days", {}))
    member_extra = int(get(policy, "member_extra_days", 0) or 0)
    credit_after = int(get(policy, "store_credit_days_after_window", 0) or 0)
    restock_fee = float(get(policy, "restocking_fee_opened_electronics", 0.0) or 0.0)
    damaged_days = int(get(policy, "damaged_refund_days", 0) or 0)
    notes = get(policy, "notes", [])
    if not isinstance(notes, list):
        notes = []

    category = str(get(target, "category", "")).lower()
    price = float(get(target, "price", 0.0) or 0.0)
    shipping = float(get(target, "shipping", 0.0) or 0.0)
    final_sale = bool(get(target, "final_sale", False))
    accessories = get(target, "accessories", [])
    if not isinstance(accessories, list):
        accessories = []

    customer_id = get(o, "customer_id")
    customer = as_dict(call("read_customer", customer_id))
    tier = str(get(customer, "tier", "")).lower()

    delivered_on = get(o, "delivered_on")
    requested_on = get(r, "requested_on")
    d_day = to_int_day(delivered_on)
    q_day = to_int_day(requested_on)
    delta = None if d_day is None or q_day is None else q_day - d_day

    holiday = False
    try:
        if isinstance(delivered_on, str) and len(delivered_on) >= 10:
            mm = int(delivered_on[5:7])
            dd = int(delivered_on[8:10])
            holiday = (mm == 11 and dd >= 15) or (mm == 12) or (mm == 1 and dd <= 31)
    except Exception:
        holiday = False

    method = "decline"
    amount = 0.0

    damaged = "damaged" in reason
    if final_sale:
        method = "decline"
    elif damaged and delta is not None and delta <= damaged_days:
        method = "card"
        amount = price + shipping
    elif category == "beauty" and opened:
        method = "decline"
    else:
        base_window = int(get(windows, category, 0) or 0)
        if tier == "plus":
            base_window += member_extra
        if holiday:
            base_window = 0
        if delta is None:
            method = "decline"
        elif delta <= base_window:
            method = "card"
        elif delta <= base_window + credit_after:
            method = "store_credit"
        else:
            method = "decline"

        if method != "decline":
            amount = price
            if opened and category == "electronics" and not holiday:
                amount = amount * (1.0 - restock_fee)
            missing_names = set()
            for a in accessories:
                if isinstance(a, dict):
                    n = get(a, "name")
                    if n is not None:
                        missing_names.add(str(n))
            for m in missing:
                if str(m) in missing_names:
                    for a in accessories:
                        if isinstance(a, dict) and str(get(a, "name")) == str(m):
                            amount -= float(get(a, "value", 0.0) or 0.0)
                            break
            if amount < 0:
                amount = 0.0
            if holiday:
                amount = price
        else:
            amount = 0.0

    amount = round(float(amount), 2)
    if method == "decline":
        call("decline_return", return_id)
        return {"method": "decline", "amount_usd": 0.0}
    call("issue_refund", return_id=return_id, amount_usd=amount, method=method)
    return {"method": method, "amount_usd": amount}
