def parse_invoice(api, doc_id: str) -> dict:
    text = ""
    try:
        doc = api.read_document(doc_id)
        if isinstance(doc, dict):
            text = doc.get("text", "")
        else:
            text = ""
    except Exception:
        return {}

    def to_number(s):
        try:
            return float(s.replace(",", "").strip())
        except Exception:
            return None

    def two_dec(x):
        return round(float(x) + 0.0, 2)

    def find_first(patterns):
        for p in patterns:
            i = text.find(p)
            if i != -1:
                return i, p
        return -1, ""

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal = 0.0
    freight = 0.0
    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    # Invoice number
    i, p = find_first(["Invoice No:", "INVOICE ", "INVOICE;", "letter is our invoice ", "Invoice No ", "INVOICE"])
    if i != -1:
        if p == "Invoice No:":
            s = text[i + len(p):].strip()
            invoice_number = s.splitlines()[0].strip().split("|")[0].strip()
        elif p == "INVOICE ":
            s = text[i + len(p):].strip()
            invoice_number = s.splitlines()[0].strip().split(";")[0].strip()
        elif p == "INVOICE;":
            parts = text[i:].splitlines()[0].split(";")
            if len(parts) >= 3:
                invoice_number = parts[2].strip()
        elif p == "letter is our invoice ":
            s = text[i + len(p):]
            invoice_number = s.split(",")[0].strip().split()[0].strip()
        elif p == "Invoice No ":
            s = text[i + len(p):].strip()
            invoice_number = s.splitlines()[0].strip()
        else:
            s = text[i + len(p):].strip()
            invoice_number = s.splitlines()[0].strip()

    # PO number
    i, p = find_first(["PO Number:", "Customer PO ", "ORDER REF;", "Thank you for your order ", "ORDER REF:", "PO Number "])
    if i != -1:
        if p == "PO Number:":
            s = text[i + len(p):].strip()
            po_number = s.splitlines()[0].strip()
        elif p == "Customer PO ":
            s = text[i + len(p):].strip()
            po_number = s.split("|")[0].strip()
        elif p == "ORDER REF;":
            s = text[i + len(p):].strip()
            po_number = s.splitlines()[0].strip()
        elif p == "Thank you for your order ":
            s = text[i + len(p):].strip()
            po_number = s.split(".")[0].strip()
        elif p == "ORDER REF:":
            s = text[i + len(p):].strip()
            po_number = s.splitlines()[0].strip()
        else:
            s = text[i + len(p):].strip()
            po_number = s.splitlines()[0].strip()

    # Date
    if "Invoice Date:" in text:
        s = text.split("Invoice Date:", 1)[1].strip().splitlines()[0].strip()
        invoice_date = s[:10]
    elif "DATE;" in text:
        s = text.split("DATE;", 1)[1].strip().splitlines()[0].strip()
        parts = s.split(";")
        if parts:
            invoice_date = parts[0].strip()
            if len(invoice_date) == 8 and invoice_date[2] == "/" and invoice_date[5] == "/":
                mm, dd, yy = invoice_date.split("/")
                invoice_date = yy + "-" + mm.zfill(2) + "-" + dd.zfill(2)
    else:
        for marker in ["Dated ", "dated "]:
            if marker in text:
                s = text.split(marker, 1)[1].strip()
                s = s.split("|")[0].strip()
                s = s.split(".")[0].strip()
                parts = s.split()
                if len(parts) >= 3:
                    day = parts[0].strip(",")
                    month = parts[1]
                    year = parts[2].strip(",")
                    months = {"January":"01","February":"02","March":"03","April":"04","May":"05","June":"06","July":"07","August":"08","September":"09","October":"10","November":"11","December":"12"}
                    if month in months:
                        invoice_date = year + "-" + months[month] + "-" + day.zfill(2)
                        break

    # Terms
    if "Terms:" in text:
        s = text.split("Terms:", 1)[1].strip().splitlines()[0].strip().lower()
        if "/" in s and "net" in s:
            a = s.split("/", 1)[0].strip()
            b = s.split("net", 1)[1].strip()
            try:
                discount_days = int(a)
            except Exception:
                discount_days = 0
            try:
                net_days = int(b)
            except Exception:
                net_days = 0
            discount_percent = discount_days
    elif "Payment terms Net " in text:
        s = text.split("Payment terms Net ", 1)[1].strip().splitlines()[0].strip()
        try:
            net_days = int(s.split()[0])
        except Exception:
            net_days = 0
    elif "TERMS;" in text:
        s = text.split("TERMS;", 1)[1].strip().splitlines()[0].strip().lower()
        if "/" in s and "n" in s:
            left, right = s.split("/", 1)
            try:
                discount_percent = float(left.strip())
            except Exception:
                discount_percent = 0.0
            r = right
            if "n" in r.lower():
                r = r.lower().replace("n", "").replace("net", "").strip()
            try:
                discount_days = int(r.split()[0])
            except Exception:
                discount_days = 0
            net_days = 30

    if net_days == 0 and "net 30" in text.lower():
        net_days = 30
    if net_days == 0 and "net 45" in text.lower():
        net_days = 45
    if discount_days == 0 and discount_percent and discount_percent.is_integer():
        discount_days = 10 if discount_percent == 1 or discount_percent == 2 else 0
    if discount_percent == 0 and discount_days:
        discount_percent = float(discount_days) if discount_days in [1, 1.5, 2] else 0.0

    # Subtotal / goods total / line totals
    if "Subtotal:" in text:
        s = text.split("Subtotal:", 1)[1].strip().splitlines()[0].strip()
        subtotal = to_number(s) or 0.0
    elif "Goods total" in text:
        s = text.split("Goods total", 1)[1].strip().split("|")[0].strip()
        subtotal = to_number(s) or 0.0
    elif "Goods total " in text:
        s = text.split("Goods total ", 1)[1].strip().split("|")[0].strip()
        subtotal = to_number(s) or 0.0
    else:
        lines = text.splitlines()
        total = 0.0
        for line in lines:
            if "x" in line and " at $" in line:
                try:
                    after = line.split("x", 1)[1]
                    qty_part = line.split("x", 1)[0].strip()
                    qty = int(qty_part)
                    price_part = after.split("at $", 1)[1].split("each")[0].strip()
                    price = float(price_part)
                    total += qty * price
                except Exception:
                    pass
            elif "|" in line:
                parts = [x.strip() for x in line.split("|")]
                if len(parts) >= 5:
                    try:
                        qty = float(parts[2].replace(",", ""))
                        unit = float(parts[3].replace(",", ""))
                        total += qty * unit
                    except Exception:
                        pass
        subtotal = total

    # Freight
    if "Freight:" in text:
        s = text.split("Freight:", 1)[1].strip().splitlines()[0].strip()
        freight = to_number(s) or 0.0
    elif "Delivery charge" in text:
        s = text.split("Delivery charge", 1)[1].strip().split("|")[0].strip()
        freight = to_number(s) or 0.0
    elif "Carriage comes to $" in text:
        s = text.split("Carriage comes to $", 1)[1].strip().splitlines()[0].strip()
        freight = to_number(s) or 0.0
    elif "SHIPPING;" in text:
        s = text.split("SHIPPING;", 1)[1].strip().splitlines()[0].strip()
        freight = to_number(s) or 0.0

    result = {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": two_dec(subtotal),
        "freight_usd": two_dec(freight),
        "discount_percent": two_dec(discount_percent),
        "discount_days": int(discount_days),
        "net_days": int(net_days),
    }
    return result
