"""Transition distillation with contract-first, practice-guided repair."""

PRIMARY_PROMPT = """You are writing one Python function that implements the contract below.

Use only the API surface and behaviors that are explicitly supported by the contract
or by successful runs. Treat failed runs as negative examples. Never invent method
names from a failure trace.

If an external object might have multiple plausible method names, use hasattr,
getattr, and callable checks and choose safely. Make the function robust to missing
attributes and unexpected return values; avoid crashing.

Contract:
{contract}

Successful runs:
{good}

Failed runs:
{bad}

Write only the function source.
"""

REPAIR_PROMPT = """The previous draft is below.

{source}

It still directly uses or relies on these missing attributes reported by failed runs:
{missing}

Current practice failures:
{failures}

Rewrite the function so it avoids those missing names, relies only on the contract
and successful runs, and guards external API calls with getattr/hasattr/callable
checks. Preserve correct behavior on successful cases.

Contract:
{contract}

Successful runs:
{good}

Failed runs:
{bad}

Relevant runs:
{episodes}

Write only the revised function source.
"""

SECOND_REPAIR_PROMPT = """The current draft is below.

{source}

It still fails on these remaining cases:
{failures}

Attributes seen in error traces:
{missing}

Refine the function without regressing on successful cases. Keep using guarded
getattr/hasattr/callable checks and only contract-supported behavior.

Contract:
{contract}

Successful runs:
{good}

Failed runs:
{bad}

Relevant runs:
{episodes}

Write only the revised function source.
"""


def unique_keep_order(items):
    seen = set()
    kept = []
    for item in items:
        if item not in seen:
            seen.add(item)
            kept.append(item)
    return kept


def render_runs(lab):
    good = []
    bad = []
    all_runs = []
    for episode in lab.episodes:
        text = lab.render(episode)
        all_runs.append(text)
        if getattr(episode, "success", False):
            good.append(text)
        else:
            bad.append(text)
    return "\n\n".join(good), "\n\n".join(bad), "\n\n".join(all_runs)


def find_missing_attributes(text):
    found = []
    if not text:
        return found
    marker = "has no attribute "
    start = 0
    while True:
        pos = text.find(marker, start)
        if pos < 0:
            break
        pos += len(marker)
        if pos >= len(text):
            break
        quote = text[pos]
        if quote in ("'", '"'):
            pos += 1
            end = text.find(quote, pos)
            if end >= 0:
                name = text[pos:end].strip()
                if name:
                    found.append(name)
                start = end + 1
                continue
        start = pos + 1
    return unique_keep_order(found)


def mentions_missing(source, missing):
    if not source or not missing:
        return False
    for name in missing:
        if ("." + name + "(") in source or (name + "(") in source:
            return True
    return False


def passed_reward(reward):
    if isinstance(reward, (int, float)):
        return reward > 0
    return bool(reward)


async def practice_all(lab, source):
    results = []
    for task_id in lab.stream():
        reward, reason, observations = await lab.practice(source, task_id)
        results.append((task_id, reward, reason, observations))
    return results


def summarize_practice(results):
    score = 0
    failcount = 0
    failures = []
    missing = []
    for task_id, reward, reason, observations in results:
        if isinstance(reward, (int, float)):
            score += reward
        else:
            score += 1 if reward else 0
        if not passed_reward(reward):
            failcount += 1
            lines = [f"Task {task_id}"]
            if reason:
                lines.append(f"Reason: {reason}")
                missing.extend(find_missing_attributes(reason))
            if observations:
                obs_text = str(observations)
                lines.append(f"Observations: {obs_text}")
                missing.extend(find_missing_attributes(obs_text))
            failures.append("\n".join(lines))
    return score, failcount, "\n\n".join(failures), unique_keep_order(missing)


async def learn(lab):
    good, bad, all_runs = render_runs(lab)

    prompt = lab.fill(
        PRIMARY_PROMPT,
        contract=lab.contract,
        good=good or "(none)",
        bad=bad or "(none)",
    )
    source = await lab.write(prompt)

    results = await practice_all(lab, source)
    score, failcount, failures, practice_missing = summarize_practice(results)

    best_source = source
    best_rank = (score, -failcount)

    episode_missing = []
    for episode in lab.episodes:
        reason = getattr(episode, "reason", "") or ""
        episode_missing.extend(find_missing_attributes(reason))
    missing = unique_keep_order(episode_missing + practice_missing)

    should_repair = bool(failcount) or (missing and mentions_missing(source, missing))
    if should_repair:
        repair = lab.fill(
            REPAIR_PROMPT,
            source=source,
            missing=", ".join(missing) or "(none)",
            failures=failures or "(none)",
            contract=lab.contract,
            good=good or "(none)",
            bad=bad or "(none)",
            episodes=all_runs or "(none)",
        )
        source2 = await lab.write(repair)
        results2 = await practice_all(lab, source2)
        score2, failcount2, failures2, practice_missing2 = summarize_practice(results2)
        rank2 = (score2, -failcount2)
        if rank2 > best_rank:
            best_source = source2
            best_rank = rank2

        missing2 = unique_keep_order(missing + practice_missing2)
        should_repair2 = bool(failcount2) or (missing2 and mentions_missing(source2, missing2))
        if should_repair2:
