            )
            source3 = await lab.write(repair2)
            results3 = await practice_all(lab, source3)
            score3, failcount3, failures3, practice_missing3 = summarize_practice(results3)
            rank3 = (score3, -failcount3)
            if rank3 > best_rank:
                best_source = source3
                best_rank = rank3

    return best_source

