def unique_keep_order(items):
    seen = set()
    kept = []
    for item in items:
        if item not in seen:
            seen.add(item)
            kept.append(item)
    return kept


def safe_get_attr(obj, name, default=None):
    try:
        return getattr(obj, name)
    except Exception:
        return default


def safe_render(lab, episode):
    try:
        return lab.render(episode)
    except Exception as exc:
        return f"(render failed: {exc})"


def positive_reward(reward):
    if isinstance(reward, bool):
        return reward
    try:
        return reward > 0
    except Exception:
        return bool(reward)


def find_missing_attributes(text):
    found = []
    if not text:
        return found
    marker = "has no attribute "
    start = 0
    while True:
        pos = text.find(marker, start)
        if pos < 0:
            break
        pos += len(marker)
        if pos >= len(text):
            break
        quote = text[pos]
        if quote in ("'", '"'):
            pos += 1
            end = text.find(quote, pos)
            if end >= 0:
                name = text[pos:end].strip()
                if name:
                    found.append(name)
                start = end + 1
                continue
        start = pos + 1
    return unique_keep_order(found)


