    return "\n\n".join(good), "\n\n".join(bad)


def format_failures(failures, limit=6):
    parts = []
    for index, failure in enumerate(failures):
        if index >= limit:
            break
        episode = failure.get("episode")
        task_id = safe_get_attr(episode, "task_id", "?")
        render = failure.get("render", "")
        reason = failure.get("reason", "")
        observations = failure.get("observations", "")
        parts.append(
            f"Task {task_id}:\n{render}\nPractice reason: {reason}\nObservations: {observations}"
        )
    if len(failures) > limit:
        parts.append(f"... {len(failures) - limit} more failures omitted ...")
    return "\n\n".join(parts)


async def collect_failures(lab, source):
    failures = []
    for episode in lab.episodes:
        task_id = safe_get_attr(episode, "task_id", None)
        if task_id is None:
            continue
        try:
            reward, reason, observations = await lab.practice(source, task_id)
        except Exception as exc:
            failures.append(
                {
                    "episode": episode,
                    "render": safe_render(lab, episode),
                    "reason": f"practice error: {exc}",
                    "observations": "",
                }
            )
            continue
        if not positive_reward(reward):
            failures.append(
                {
                    "episode": episode,
                    "render": safe_render(lab, episode),
                    "reason": reason,
                    "observations": observations,
                }
            )
    return failures


async def learn(lab):
    good, bad = render_runs(lab)

    missing = []
    for episode in lab.episodes:
        reason = safe_get_attr(episode, "reason", "") or ""
        missing.extend(find_missing_attributes(str(reason)))
    missing = unique_keep_order(missing)
    missing_text = ", ".join(missing) if missing else "(none)"

    if good:
        prompt = lab.fill(
            BASE_PROMPT,
            contract=lab.contract,
            good=good or "(none)",
            missing=missing_text,
        )
    else:
        prompt = lab.fill(
            BASE_PROMPT_NO_GOOD,
            contract=lab.contract,
            bad=bad or "(none)",
            missing=missing_text,
        )

    source = await lab.write(prompt)

    for _ in range(2):
        failures = await collect_failures(lab, source)
        if not failures:
            break

        failure_missing = []
        for failure in failures:
            reason = failure.get("reason", "") or ""
            observations = failure.get("observations", "") or ""
            failure_missing.extend(find_missing_attributes(reason))
            failure_missing.extend(find_missing_attributes(str(observations)))
        all_missing = unique_keep_order(missing + failure_missing)
        repair = lab.fill(
            REPAIR_PROMPT,
            source=source,
            contract=lab.contract,
            good=good or "(none)",
            failures=format_failures(failures),
            missing=", ".join(all_missing) if all_missing else "(none)",
        )
        new_source = await lab.write(repair)
        if new_source == source:
            break
        source = new_source

    return source

