        return float(s)

    def parse_date(s):
        s = s.strip()
        months = {
            "january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6,
            "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12
        }
        if "/" in s:
            parts = s.split("/")
            if len(parts[0]) == 4:
                y, m, d = parts
            else:
                m, d, y = parts
            return y.zfill(4) + "-" + d.zfill(2) + "-" + m.zfill(2)
        parts = s.replace(",", "").split()
        if len(parts) >= 3:
            d = parts[0]
            m = str(months[parts[1].lower()])
            y = parts[2]
            return y.zfill(4) + "-" + m.zfill(2) + "-" + d.zfill(2)
        return s

    def parse_terms(s):
        s = s.strip().lower().replace("payment terms", "").replace("terms", "").strip()
        dp = 0
