            a, b = s.split("/", 1)
            try:
                dp = int(a.strip())
            except Exception:
                dp = 0
            b = b.strip()
            if " " in b:
                first, rest = b.split(" ", 1)
            else:
                first, rest = b, ""
            try:
                dd = int(first)
            except Exception:
                dd = 0
            nums = []
            cur = ""
            for ch in rest:
