                    cur += ch
                else:
                    if cur:
                        nums.append(int(cur))
                        cur = ""
            if cur:
                nums.append(int(cur))
            if nums:
                nd = nums[-1]
        else:
            if "net" in s:
                i = s.find("net")
                tail = s[i + 3:].strip()
                num = ""
                for ch in tail:
                    if ch.isdigit():
                        num += ch
                    elif num:
                        break
                if num:
