def parse_invoice(api, doc_id: str) -> dict:
    text = api.read_document(doc_id)["text"]

    def norm(s):
        return s.replace("\r", "\n")

    def money(s):
        s = s.strip().replace("$", "").replace(",", "")
        return float(s)

    def parse_date(s):
        s = s.strip()
        months = {
            "january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6,
            "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12
        }
        if "/" in s:
            parts = s.split("/")
            if len(parts) == 3:
                a, b, c = parts
                if len(a) == 4:
                    y, m, d = a, b, c
                else:
                    m, d, y = a, b, c
                return y.zfill(4) + "-" + m.zfill(2) + "-" + d.zfill(2)
            return s
        parts = s.replace(",", "").split()
        if len(parts) >= 3:
            d = parts[0]
            m = str(months[parts[1].lower()])
            y = parts[2]
            return y.zfill(4) + "-" + m.zfill(2) + "-" + d.zfill(2)
        return s

    def parse_terms(s):
        s = s.strip().lower().replace("payment terms", "").replace("terms", "").strip()
        dp = 0
        dd = 0
        nd = 0
        if "/" in s:
            a, b = s.split("/", 1)
            try:
                dp = int(a.strip())
            except Exception:
                dp = 0
            b = b.strip()
            if " " in b:
                first, rest = b.split(" ", 1)
            else:
                first, rest = b, ""
            try:
                dd = int(first)
            except Exception:
                dd = 0
            nums = []
            cur = ""
            for ch in rest:
                if ch.isdigit():
                    cur += ch
                else:
                    if cur:
                        nums.append(int(cur))
                        cur = ""
            if cur:
                nums.append(int(cur))
            if nums:
                nd = nums[-1]
        else:
            if "net" in s:
                i = s.find("net")
                tail = s[i + 3:].strip()
                num = ""
                for ch in tail:
                    if ch.isdigit():
                        num += ch
                    elif num:
                        break
                if num:
                    nd = int(num)
        return dp, dd, nd

    def parse_item_total(lines):
        total = 0.0
        for line in lines:
            if " at $" in line and " x " in line:
                left, right = line.split(" at $", 1)
                qty_text = left.split(" x ", 1)[0].strip().split()[-1]
                try:
                    qty = int(qty_text)
                    price = float(right.split()[0].replace(",", ""))
                    total += qty * price
                except Exception:
                    pass
            elif "|" in line:
                cols = [x.strip() for x in line.split("|")]
                if len(cols) >= 5:
                    try:
                        qty = int(cols[2])
                        price = float(cols[3].replace(",", ""))
                        total += qty * price
                    except Exception:
                        pass
                elif len(cols) >= 4 and cols[0] and cols[0][0].isalnum():
                    try:
                        qty = int(cols[2])
                        price = float(cols[3].replace(",", ""))
                        total += qty * price
                    except Exception:
                        pass
        return round(total, 2)

    t = norm(text)
    lines = [x.strip() for x in t.split("\n") if x.strip()]

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal = 0.0
    freight = 0.0
    discount_percent = 0
    discount_days = 0
    net_days = 0

    if ";" in t and "ITEM;DESCRIPTION;QTY;PRICE" in t:
        for line in lines:
            if line.startswith("DATE;"):
                invoice_date = parse_date(line.split(";", 1)[1])
            elif line.startswith("ORDER REF;"):
                po_number = line.split(";", 1)[1].strip()
            elif line.startswith("TERMS;"):
                discount_percent, discount_days, net_days = parse_terms(line.split(";", 1)[1])
            elif line.startswith("SHIPPING;"):
                freight = money(line.split(";", 1)[1])
            elif ";INVOICE;" in line:
                invoice_number = line.split(";")[-1].strip()
        subtotal = parse_item_total(lines)

    elif "Invoice No:" in t or "INVOICE " in t or "Invoice No" in t:
        for line in lines:
            if line.startswith("Invoice No:"):
                invoice_number = line.split(":", 1)[1].strip()
            elif line.startswith("Invoice Date:"):
                invoice_date = parse_date(line.split(":", 1)[1])
            elif line.startswith("PO Number:"):
                po_number = line.split(":", 1)[1].strip()
            elif line.startswith("Terms:"):
                discount_percent, discount_days, net_days = parse_terms(line.split(":", 1)[1])
            elif line.startswith("Subtotal:"):
