            elif line.startswith("Freight:"):
                freight = money(line.split(":", 1)[1])

    else:
        for line in lines:
            low = line.lower()
            if "invoice" in low and "dated" in low:
                parts = line.replace(".", "").split()
                for i, p in enumerate(parts):
                    if p.lower() == "invoice" and i + 1 < len(parts):
