            if "thank you for your order" in low:
                i = line.find("PO-")
                if i >= 0:
                    po_number = line[i:].split()[0].strip().strip(".")
            if "carriage comes to" in low:
                freight = money(line.split("$")[-1])
            if "settle within" in low:
                nums = []
                cur = ""
                for ch in line:
                    if ch.isdigit():
                        cur += ch
                    else:
                        if cur:
                            nums.append(int(cur))
                            cur = ""
                if cur:
                    nums.append(int(cur))
                if nums:
                    net_days = nums[0]
                if "%" in line and "within" in low:
