                        discount_percent = float(line.split("%")[0].split()[-1])
                    except Exception:
                        discount_percent = 0
                    if len(nums) > 1:
                        discount_days = nums[1]
            if "we supplied:" in low:
                item_total = 0.0
                items = line.split(":", 1)[1].split(";")
                for item in items:
                    if " at $" in item:
