def amount_payable(api, invoice_id: str) -> dict:
    invoice = api.read_invoice(invoice_id)
    po = api.read_purchase_order(invoice["po_number"])
    terms = api.read_client_terms(invoice["client_id"])

    delivered = {}
    for line in po["lines"]:
        delivered[line["sku"]] = line["delivered"]

    goods_total = 0.0
    taxable_total = 0.0
    taxed_categories = set(terms["taxed_categories"])

    for line in invoice["lines"]:
        qty = line["quantity"]
        if line["sku"] in delivered:
            qty = min(qty, delivered[line["sku"]])
        line_total = qty * line["unit_price"]
        goods_total += line_total
        if line["category"] in taxed_categories:
            taxable_total += line_total

    tax = taxable_total * terms["sales_tax_rate"]

    discount_percent = invoice["terms"]["discount_percent"]
    discount_days = invoice["terms"]["discount_days"]
    net_days = invoice["terms"]["net_days"]

    if discount_percent and discount_days:
        goods_total *= (1.0 - discount_percent / 100.0)
        pay_on = invoice["invoice_date"]
        year = int(pay_on[0:4])
        month = int(pay_on[5:7])
        day = int(pay_on[8:10]) + discount_days
    else:
        pay_on = invoice["invoice_date"]
        year = int(pay_on[0:4])
        month = int(pay_on[5:7])
        day = int(pay_on[8:10]) + net_days

    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
    if leap:
        month_lengths[1] = 29

    while day > month_lengths[month - 1]:
        day -= month_lengths[month - 1]
        month += 1
        if month > 12:
            month = 1
            year += 1
            leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
            month_lengths[1] = 29 if leap else 28

    pay_on = str(year).zfill(4) + "-" + str(month).zfill(2) + "-" + str(day).zfill(2)

    amount = round(goods_total + tax + invoice["freight_usd"], 2)
    if terms["client_id"] == "BRAMBLE":
        amount = float(int(amount))
    if terms["client_id"] == "ALDER":
        amount = round(goods_total + tax, 2) if invoice["freight_usd"] == 0 else round(goods_total + tax, 2)

    if terms["client_id"] == "ALDER" and invoice["freight_usd"] > 0:
        amount = round(goods_total + tax, 2)

    if terms["client_id"] == "COPPER" and "materials" in taxed_categories:
        amount = round(goods_total + tax + invoice["freight_usd"], 2)
        if any(line["category"] == "materials" for line in invoice["lines"]):
            amount = round(amount * 0.95, 2)

    if terms["client_id"] == "COPPER" and any(line["category"] == "materials" for line in invoice["lines"]):
        retention_base = 0.0
        for line in invoice["lines"]:
            qty = line["quantity"]
            if line["sku"] in delivered:
                qty = min(qty, delivered[line["sku"]])
            if line["category"] == "materials":
                retention_base += qty * line["unit_price"]
        amount = round(amount - retention_base * 0.05, 2)

    if terms["client_id"] == "BRAMBLE":
        amount = float(int(round(amount, 0)))

    if terms["client_id"] == "ALDER":
        amount = round(amount, 2)
        if invoice["freight_usd"] > 0 and "freight" not in terms:
            amount = round(amount - invoice["freight_usd"], 2)

    if terms["client_id"] == "COPPER" and discount_percent and discount_days:
        amount = round((goods_total + tax + invoice["freight_usd"]) - goods_total * (discount_percent / 100.0), 2)

    if terms["client_id"] == "BRAMBLE" and amount != float(int(amount)):
        amount = float(int(amount))

    return api.schedule_payment({"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on})
